INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,66,'An-Nahl','وَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةࣰۖ نُّسۡقِيكُم مِّمَّا فِي بُطُونِهِۦ مِنۢ بَيۡنِ فَرۡثࣲ وَدَمࣲ لَّبَنًا خَالِصࣰ ا سَآئِغࣰ ا لِّلشَّٰرِبِينَ','اور تمہارے لیے چارپایوں میں بھی (مقام) عبرت (وغور) ہے کہ ان کے پیٹوں میں جو گوبر اور لہو ہے اس سے ہم تم کو خالص دودھ پلاتے ہیں جو پینے والوں کے لیے خوشگوار ہے','And there is certainly a lesson for you in cattle: We give you to drink of what is in their bellies, from between digested food and blood: pure milk, pleasant to drink','और इसमें शक़ नहीं कि चौपायों में भी तुम्हारे लिए (इबरत की बात) है कि उनके पेट में ख़ाक, बला, गोबर और ख़ून (जो कुछ भरा है) उसमें से हमे तुमको ख़ालिस दूध पिलाते हैं जो पीने वालों के लिए खुशगवार है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,67,'An-Nahl','وَمِن ثَمَرَٰتِ ٱلنَّخِيلِ وَٱلۡأَعۡنَٰبِ تَتَّخِذُونَ مِنۡهُ سَكَرࣰ ا وَرِزۡقًا حَسَنًاۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةࣰ لِّقَوۡمࣲ يَعۡقِلُونَ','اور کھجور اور انگور کے میووں سے بھی (تم پینے کی چیزیں تیار کرتے ہو کہ ان سے شراب بناتے ہو) اور عمدہ رزق (کھاتے ہو) جو لوگ سمجھ رکھتے ہیں ان کے لیے ان (چیزوں) میں (قدرت خدا کی) نشانی ہے','And from the fruits of palm trees and grapevines you derive intoxicants as well as wholesome provision. Surely in this is a sign for those who understand','और इसी तरह खुरमें और अंगूर के फल से (हम तुमको शीरा पिलाते हैं) जिसकी (कभी तो) तुम शराब बना लिया करते हो और कभी अच्छी रोज़ी (सिरका वगैरह) इसमें शक नहीं कि इसमें भी समझदार लोगों के लिए (क़ुदरत ख़ुदा की) बड़ी निशानी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,68,'An-Nahl','وَأَوۡحَىٰ رَبُّكَ إِلَى ٱلنَّحۡلِ أَنِ ٱتَّخِذِي مِنَ ٱلۡجِبَالِ بُيُوتࣰ ا وَمِنَ ٱلشَّجَرِ وَمِمَّا يَعۡرِشُونَ','اور تمہارے پروردگار نے شہد کی مکھیوں کو ارشاد فرمایا کہ پہاڑوں میں اور درختوں میں اور اونچی اونچی چھتریوں میں جو لوگ بناتے ہیں گھر بنا','And your Lord inspired the bees: “Make ˹your˺ homes in the mountains, the trees, and in what people construct','और (ऐ रसूल) तुम्हारे परवरदिगार ने शहद की मक्खियों के दिल में ये बात डाली कि तू पहाड़ों और दरख्तों और ऊँची ऊँची ट्ट्टियाँ (और मकानात पाट कर) बनाते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,69,'An-Nahl','ثُمَّ كُلِي مِن كُلِّ ٱلثَّمَرَٰتِ فَٱسۡلُكِي سُبُلَ رَبِّكِ ذُلُلࣰ اۚ يَخۡرُجُ مِنۢ بُطُونِهَا شَرَابࣱ مُّخۡتَلِفٌ أَلۡوَٰنُهُۥ فِيهِ شِفَآءࣱ لِّلنَّاسِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةࣰ لِّقَوۡمࣲ يَتَفَكَّرُونَ','اور ہر قسم کے میوے کھا۔ اور اپنے پروردگار کے صاف رستوں پر چلی جا۔ اس کے پیٹ سے پینے کی چیز نکلتی ہے جس کے مختلف رنگ ہوتے ہیں اس میں لوگوں (کے کئی امراض) کی شفا ہے۔ بےشک سوچنے والوں کے لیے اس میں بھی نشانی ہے','and feed from ˹the flower of˺ any fruit ˹you please˺ and follow the ways your Lord has made easy for you.” From their bellies comes forth liquid of varying colours, in which there is healing for people. Surely in this is a sign for those who reflect','उनमें अपने छत्ते बना फिर हर तरह के फलों (के पूर से) (उनका अर्क़) चूस कर फिर अपने परवरदिगार की राहों में ताबेदारी के साथ चली मक्खियों के पेट से पीने की एक चीज़ निकलती है (शहद) जिसके मुख्तलिफ रंग होते हैं इसमें लोगों (के बीमारियों) की शिफ़ा (भी) है इसमें शक़ नहीं कि इसमें ग़ौर व फ़िक्र करने वालों के वास्ते (क़ुदरते ख़ुदा की बहुत बड़ी निशानी है)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,70,'An-Nahl','وَٱللَّهُ خَلَقَكُمۡ ثُمَّ يَتَوَفَّىٰكُمۡۚ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرۡذَلِ ٱلۡعُمُرِ لِكَيۡ لَا يَعۡلَمَ بَعۡدَ عِلۡمࣲ شَيۡـًٔاۚ إِنَّ ٱللَّهَ عَلِيمࣱ قَدِيرࣱ‏','اور خدا ہی نے تم کو پیدا کیا۔ پھر وہی تم کو موت دیتا ہے اور تم میں بعض ایسے ہوتے ہیں کہ نہایت خراب عمر کو پہنچ جاتے ہیں اور (بہت کچھ) جاننے کے بعد ہر چیز سے بےعلم ہوجاتے ہیں۔ بےشک خدا (سب کچھ) جاننے والا (اور) قدرت والا ہے','Allah has created you, and then causes you to die. And some of you are left to reach the most feeble stage of life so that they may know nothing after having known much. Indeed, Allah is All-Knowing, Most Capable','और ख़ुदा ही ने तुमको पैदा किया फिर वही तुमको (दुनिया से) उठा लेगा और तुममें से बाज़ ऐसे भी हैं जो ज़लील ज़िन्दगी (सख्त बुढ़ापे) की तरफ लौटाए जाते हैं (बहुत कुछ) जानने के बाद (ऐसे सड़ीले हो गए कि) कुछ नहीं जान सके बेशक ख़ुदा (सब कुछ) जानता और (हर तरह की) कुदरत रखता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,71,'An-Nahl','وَٱللَّهُ فَضَّلَ بَعۡضَكُمۡ عَلَىٰ بَعۡضࣲ فِي ٱلرِّزۡقِۚ فَمَا ٱلَّذِينَ فُضِّلُواْ بِرَآدِّي رِزۡقِهِمۡ عَلَىٰ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَهُمۡ فِيهِ سَوَآءٌۚ أَفَبِنِعۡمَةِ ٱللَّهِ يَجۡحَدُونَ','اور خدا نے رزق (ودولت) میں بعض کو بعض پر فضیلت دی ہے تو جن لوگوں کو فضیلت دی ہے وہ اپنا رزق اپنے مملوکوں کو تو دے ڈالنے والے ہیں نہیں کہ سب اس میں برابر ہوجائیں۔ تو کیا یہ لوگ نعمت الہیٰ کے منکر ہیں','And Allah has favoured some of you over others in provision. But those who have been much favoured would not share their wealth with those ˹bondspeople˺ in their possession, making them their equals. Do they then deny Allah’s favours','और ख़ुदा ही ने तुममें से बाज़ को बाज़ पर रिज़क (दौलत में) तरजीह दी है फिर जिन लोगों को रोज़ी ज्यादा दी गई है वह लोग अपनी रोज़ी में से उन लोगों को जिन पर उनका दस्तरस (इख्तेयार) है (लौन्डी ग़ुलाम वग़ैरह) देने वाला नहीं (हालॉकि इस माल में तो सब के सब मालिक गुलाम वग़ैरह) बराबर हैं तो क्या ये लोग ख़ुदा की नेअमत के मुन्किर हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,72,'An-Nahl','وَٱللَّهُ جَعَلَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجࣰ ا وَجَعَلَ لَكُم مِّنۡ أَزۡوَٰجِكُم بَنِينَ وَحَفَدَةࣰ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِۚ أَفَبِٱلۡبَٰطِلِ يُؤۡمِنُونَ وَبِنِعۡمَتِ ٱللَّهِ هُمۡ يَكۡفُرُونَ','اور خدا ہی نے تم میں سے تمہارے لیے عورتیں پیدا کیں اور عورتوں سے تمہارے بیٹے اور پوتے پیدا کیے اور کھانے کو تمہیں پاکیزہ چیزیں دیں۔ تو کیا بےاصل چیزوں پر اعتقاد رکھتے اور خدا کی نعمتوں سے انکار کرتے ہیں','And Allah has made for you spouses of your own kind, and given you through your spouses children and grandchildren. And He has granted you good, lawful provisions. Are they then faithful to falsehood and ungrateful for Allah’s favours','और ख़ुदा ही ने तुम्हारे लिए बीबियाँ तुम ही में से बनाई और उसी ने तुम्हारे वास्ते तुम्हारी बीवियों से बेटे और पोते पैदा किए और तुम्हें पाक व पाकीज़ा रोज़ी खाने को दी तो क्या ये लोग बिल्कुल बातिल (सुल्तान बुत वग़ैरह) पर ईमान रखते हैं और ख़ुदा की नेअमत (वहदानियत वग़ैरह से) इन्कार करते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,73,'An-Nahl','وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمۡلِكُ لَهُمۡ رِزۡقࣰ ا مِّنَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ شَيۡـࣰٔ ا وَلَا يَسۡتَطِيعُونَ','اور خدا کے سوا ایسوں کو پوجتے ہیں جو ان کو آسمانوں اور زمین میں روزی دینے کا ذرا بھی اختیار نہیں رکھتے اور نہ کسی اور طرح کا مقدور رکھتے ہیں','Yet they worship besides Allah those ˹idols˺ who do not afford them any provision from the heavens and the earth, nor do they have the power to','और ख़ुदा को छोड़कर ऐसी चीज़ की परसतिश करते हैं जो आसमानों और ज़मीन में से उनको रिज़क़ देने का कुछ भी न एख्तियार रखते हैं और न कुदरत हासिल कर सकते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,74,'An-Nahl','فَلَا تَضۡرِبُواْ لِلَّهِ ٱلۡأَمۡثَالَۚ إِنَّ ٱللَّهَ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ','تو (لوگو) خدا کے بارے میں (غلط) مثالیں نہ بناؤ۔ (صحیح مثالوں کا طریقہ) خدا ہی جانتا ہے اور تم نہیں جانتے','So do not set up equals to Allah, for Allah certainly knows and you do not know','तो तुम (दुनिया के लोगों पर कयास करके ख़ुद) मिसालें न गढ़ो बेशक ख़ुदा (सब कुछ) जानता है और तुम नहीं जानते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,75,'An-Nahl','۞ضَرَبَ ٱللَّهُ مَثَلًا عَبۡدࣰ ا مَّمۡلُوكࣰ ا لَّا يَقۡدِرُ عَلَىٰ شَيۡءࣲ وَمَن رَّزَقۡنَٰهُ مِنَّا رِزۡقًا حَسَنࣰ ا فَهُوَ يُنفِقُ مِنۡهُ سِرࣰّ ا وَجَهۡرًاۖ هَلۡ يَسۡتَوُۥنَۚ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ','خدا ایک اور مثال بیان فرماتا ہے کہ ایک غلام ہے جو (بالکل) دوسرے کے اختیار میں ہے اور کسی چیز پر قدرت نہیں رکھتا اور ایک ایسا شخص ہے جس کو ہم نے اپنے ہاں سے (بہت سا) مال طیب عطا فرمایا ہے اور وہ اس میں سے (رات دن) پوشیدہ اور ظاہر خرچ کرتا رہتا ہے تو کیا یہ دونوں شخص برابر ہیں؟ (ہرگز نہیں) الحمدلله لیکن ان میں سے اکثر لوگ نہیں سمجھ رکھتے','Allah sets forth a parable: a slave who lacks all means, compared to a ˹free˺ man to whom We granted a good provision, of which he donates ˹freely,˺ openly and secretly. Are they equal? Praise be to Allah. In fact, most of them do not know','एक मसल ख़ुदा ने बयान फरमाई कि एक ग़ुलाम है जो दूसरे के कब्जे में है (और) कुछ भी एख्तियार नहीं रखता और एक शख़्श वह है कि हमने उसे अपनी बारगाह से अच्छी (खासी) रोज़ी दे रखी है तो वह उसमें से छिपा के दिखा के (ग़रज़ हर तरह ख़ुदा की राह में) ख़र्च करता है क्या ये दोनो बराबर हो सकते हैं (हरगिज़ नहीं) अल्हमदोलिल्लाह (कि वह भी उसके मुक़र्रर हैं) मगर उनके बहुतेरे (इतना भी) नहीं जानते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,76,'An-Nahl','وَضَرَبَ ٱللَّهُ مَثَلࣰ ا رَّجُلَيۡنِ أَحَدُهُمَآ أَبۡكَمُ لَا يَقۡدِرُ عَلَىٰ شَيۡءࣲ وَهُوَ كَلٌّ عَلَىٰ مَوۡلَىٰهُ أَيۡنَمَا يُوَجِّههُّ لَا يَأۡتِ بِخَيۡرٍ هَلۡ يَسۡتَوِي هُوَ وَمَن يَأۡمُرُ بِٱلۡعَدۡلِ وَهُوَ عَلَىٰ صِرَٰطࣲ مُّسۡتَقِيمࣲ‏','اور خدا ایک اور مثال بیان فرماتا ہے کہ دو آدمی ہیں ایک اُن میں سے گونگا (اور دوسرے کی ملک) ہے (بےاختیار وناتوان) کہ کسی چیز پر قدرت نہیں رکھتا۔ اور اپنے مالک کو دوبھر ہو رہا ہے وہ جہاں اُسے بھیجتا ہے (خیر سے کبھی) بھلائی نہیں لاتا۔ کیا ایسا (گونگا بہرا) اور وہ شخص جو (سنتا بولتا اور) لوگوں کو انصاف کرنے کا حکم دیتا ہے اور خود سیدھے راستے پر چل رہا ہے دونوں برابر ہیں؟','And Allah sets forth a parable of two men: one of them is dumb, incapable of anything. He is a burden on his master. Wherever he is sent, he brings no good. Can such a person be equal to the one who commands justice and is on the Straight Path','और ख़ुदा एक दूसरी मसल बयान फरमाता है दो आदमी हैं कि एक उनमें से बिल्कुल गूँगा उस पर गुलाम जो कुछ भी (बात वग़ैरह की) कुदरत नहीं रखता और (इस वजह से) वह अपने मालिक को दूभर हो रहा है कि उसको जिधर भेजता है (ख़ैर से) कभी भलाई नहीं लाता क्या ऐसा ग़ुलाम और वह शख़्श जो (लोगों को) अदल व मियाना रवी का हुक्म करता है वह खुद भी ठीक सीधी राह पर क़ायम है (दोनों बराबर हो सकते हैं (हरगिज़ नहीं)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,77,'An-Nahl','وَلِلَّهِ غَيۡبُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَمَآ أَمۡرُ ٱلسَّاعَةِ إِلَّا كَلَمۡحِ ٱلۡبَصَرِ أَوۡ هُوَ أَقۡرَبُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءࣲ قَدِيرࣱ‏','اور آسمانوں اور زمین کا علم خدا ہی کو ہے اور (خدا کے نزدیک) قیامت کا آنا یوں ہے جیسے آنکھ کا جھپکنا بلکہ اس سے بھی جلد تر۔ کچھ شک نہیں کہ خدا ہر چیز پر قادر ہے','To Allah ˹alone˺ belongs ˹the knowledge of˺ the unseen in the heavens and the earth. Bringing about the Hour would only take the blink of an eye, or even less. Surely Allah is Most Capable of everything','और सारे आसमान व ज़मीन की ग़ैब की बातें ख़ुदा ही के लिए मख़सूस हैं और ख़ुदा क़यामत का वाकेए होना तो ऐसा है जैसे पलक का झपकना बल्कि इससे भी जल्दी बेशक ख़ुदा हर चीज़ पर क़ुदरत कामेला रखता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,78,'An-Nahl','وَٱللَّهُ أَخۡرَجَكُم مِّنۢ بُطُونِ أُمَّهَٰتِكُمۡ لَا تَعۡلَمُونَ شَيۡـࣰٔ ا وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَ لَعَلَّكُمۡ تَشۡكُرُونَ','اور خدا ہی نے تم کو تمہاری ماؤں کے شکم سے پیدا کیا کہ تم کچھ نہیں جانتے تھے۔ اور اس نے تم کو کان اور آنکھیں اور دل (اور اُن کے علاوہ اور) اعضا بخشے تاکہ تم شکر کرو','And Allah brought you out of the wombs of your mothers while you knew nothing, and gave you hearing, sight, and intellect so perhaps you would be thankful','और ख़ुदा ही ने तुम्हें तुम्हारी माओं के पेट से निकाला (जब) तुम बिल्कुल नासमझ थे और तुम को कान दिए और ऑंखें (अता की) दिल (इनायत किए) ताकि तुम शुक्र करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,79,'An-Nahl','أَلَمۡ يَرَوۡاْ إِلَى ٱلطَّيۡرِ مُسَخَّرَٰتࣲ فِي جَوِّ ٱلسَّمَآءِ مَا يُمۡسِكُهُنَّ إِلَّا ٱللَّهُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتࣲ لِّقَوۡمࣲ يُؤۡمِنُونَ','کیا ان لوگوں نے پرندوں کو نہیں دیکھا کہ آسمان کی ہوا میں گھرے ہوئے (اُڑتے رہتے) ہیں۔ ان کو خدا ہی تھامے رکھتا ہے۔ ایمان والوں کے لیے اس میں (بہت سی) نشانیاں ہیں','Have they not seen the birds glide in the open sky? None holds them up except Allah. Surely in this are signs for those who believe','क्या उन लोगों ने परिन्दों की तरफ ग़ौर नहीं किया जो आसमान के नीचे हवा में घिरे हुए (उड़ते रहते हैं) उनको तो बस ख़ुदा ही (गिरने से ) रोकता है बेशक इसमें भी (कुदरते ख़ुदा की) ईमानदारों के लिए बहुत सी निशानियाँ हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,80,'An-Nahl','وَٱللَّهُ جَعَلَ لَكُم مِّنۢ بُيُوتِكُمۡ سَكَنࣰ ا وَجَعَلَ لَكُم مِّن جُلُودِ ٱلۡأَنۡعَٰمِ بُيُوتࣰ ا تَسۡتَخِفُّونَهَا يَوۡمَ ظَعۡنِكُمۡ وَيَوۡمَ إِقَامَتِكُمۡ وَمِنۡ أَصۡوَافِهَا وَأَوۡبَارِهَا وَأَشۡعَارِهَآ أَثَٰثࣰ ا وَمَتَٰعًا إِلَىٰ حِينࣲ‏','اور خدا ہی نے تمہارے لیے گھروں کو رہنے کی جگہ بنایا اور اُسی نے چوپایوں کی کھالوں سے تمہارے لیے ڈیرے بنائے۔ جن کو تم سبک دیکھ کر سفر اور حضر میں کام میں لاتے ہو اور اُن کی اون، پشم اور بالوں سے تم اسباب اور برتنے کی چیزیں (بناتے ہو جو) مدت تک (کام دیتی ہیں)','And Allah has made your homes a place to rest, and has given you tents from the hide of animals, light to handle when you travel and when you camp. And out of their wool, fur, and hair He has given you furnishings and goods for a while','और ख़ुदा ही ने तुम्हारे घरों को तुम्हारा ठिकाना क़रार दिया और उसी ने तुम्हारे वास्ते चौपायों की खालों से तुम्हारे लिए (हलके फुलके) डेरे (ख़ेमे) बना जिन्हें तुम हलका पाकर अपने सफर और हजर (ठहरने) में काम लाते हो और इन चारपायों की ऊन और रुई और बालो से एक वक्त ख़ास (क़यामत तक) के लिए तुम्हारे बहुत से असबाब और अबकार आमद (काम की) चीज़े बनाई');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,81,'An-Nahl','وَٱللَّهُ جَعَلَ لَكُم مِّمَّا خَلَقَ ظِلَٰلࣰ ا وَجَعَلَ لَكُم مِّنَ ٱلۡجِبَالِ أَكۡنَٰنࣰ ا وَجَعَلَ لَكُمۡ سَرَٰبِيلَ تَقِيكُمُ ٱلۡحَرَّ وَسَرَٰبِيلَ تَقِيكُم بَأۡسَكُمۡۚ كَذَٰلِكَ يُتِمُّ نِعۡمَتَهُۥ عَلَيۡكُمۡ لَعَلَّكُمۡ تُسۡلِمُونَ','اور خدا ہی نے تمہارے (آرام کے) لیے اپنی پیدا کی ہوئی چیزوں کے سائے بنائے اور پہاڑوں میں غاریں بنائیں اور کُرتے بنائے جو تم کو گرمی سے بچائیں۔ اور (ایسے) کُرتے (بھی) جو تم کو اسلحہ جنگ (کے ضرر) سے محفوظ رکھیں۔ اسی طرح خدا اپنا احسان تم پر پورا کرتا ہے تاکہ تم فرمانبردار بنو','And Allah has provided you shade out of what He created, and has given you shelter in the mountains. He has also provided you with clothes protecting you from the heat ˹and cold˺, and armour shielding you in battle. This is how He perfects His favour upon you, so perhaps you will ˹fully˺ submit ˹to Him˺','और ख़ुदा ही ने तुम्हारे आराम के लिए अपनी पैदा की हुईचीज़ों के साए बनाए और उसी ने तुम्हारे (छिपने बैठने) के वास्ते पहाड़ों में घरौन्दे (ग़ार वग़ैरह) बनाए और उसी ने तुम्हारे लिए कपड़े बनाए जो तुम्हें (सर्दी) गर्मी से महफूज़ रखें और (लोहे) के कुर्ते जो तुम्हें हाथियों की ज़द (मार) से बचा लंग़ यूँ ख़ुदा अपनी नेअमत तुम पर पूरी करता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,82,'An-Nahl','فَإِن تَوَلَّوۡاْ فَإِنَّمَا عَلَيۡكَ ٱلۡبَلَٰغُ ٱلۡمُبِينُ','اور اگر یہ لوگ اعتراض کریں تو (اے پیغمبر) تمہارا کام فقط کھول کر سنا دینا ہے','But if they turn away, then your duty ˹O Prophet˺ is only to deliver ˹the message˺ clearly','तुम उसकी फरमाबरदारी करो उस पर भी अगर ये लोग (ईमान से) मुँह फेरे तो तुम्हारा फर्ज सिर्फ (एहकाम का) साफ पहुँचा देना है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,83,'An-Nahl','يَعۡرِفُونَ نِعۡمَتَ ٱللَّهِ ثُمَّ يُنكِرُونَهَا وَأَكۡثَرُهُمُ ٱلۡكَٰفِرُونَ','یہ خدا کی نعمتوں سے واقف ہیں۔ مگر (واقف ہو کر) اُن سے انکار کرتے ہیں اور یہ اکثر ناشکرے ہیں','They are aware of Allah’s favours, but still deny them. And most of them are ˹truly˺ ungrateful','(बस) ये लोग ख़ुदा की नेअमतों को पहचानते हैं फिर (जानबुझ कर) उनसे मुकर जाते हैं और इन्हीं में से बहुतेरे नाशुक्रे हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,84,'An-Nahl','وَيَوۡمَ نَبۡعَثُ مِن كُلِّ أُمَّةࣲ شَهِيدࣰ ا ثُمَّ لَا يُؤۡذَنُ لِلَّذِينَ كَفَرُواْ وَلَا هُمۡ يُسۡتَعۡتَبُونَ','اور جس دن ہم ہر اُمت میں سے گواہ (یعنی پیغمبر) کھڑا کریں گے تو نہ تو کفار کو (بولنے کی) اجازت ملے گی اور نہ اُن کے عذر قبول کئے جائیں گے','˹Consider, O Prophet,˺ the Day We will call ˹a prophet as˺ a witness from every faith-community. Then the disbelievers will neither be allowed to plead nor appease ˹their Lord˺','और जिस दिन हम एक उम्मत में से (उसके पैग़म्बरों को) गवाह बनाकर क़ब्रों से उठा खड़ा करेगे फिर तो काफिरों को न (बात करने की) इजाज़त दी जाएगी और न उनका उज्र (जवाब) ही सुना जाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,85,'An-Nahl','وَإِذَا رَءَا ٱلَّذِينَ ظَلَمُواْ ٱلۡعَذَابَ فَلَا يُخَفَّفُ عَنۡهُمۡ وَلَا هُمۡ يُنظَرُونَ','اور جب ظالم لوگ عذاب دیکھ لیں گے تو پھر نہ تو اُن کے عذاب ہی میں تخفیف کی جائے گی اور نہ اُن کو مہلت ہی دی جائے گی','And when the wrongdoers face the punishment, it will not be lightened for them, nor will they be delayed ˹from it˺','और जिन लोगों ने (दुनिया में) शरारतें की थी जब वह अज़ाब को देख लेगें तो उनके अज़ाब ही में तख़फ़ीफ़ की जाएगी और न उनको मोहलत ही दी जाएगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,86,'An-Nahl','وَإِذَا رَءَا ٱلَّذِينَ أَشۡرَكُواْ شُرَكَآءَهُمۡ قَالُواْ رَبَّنَا هَٰٓؤُلَآءِ شُرَكَآؤُنَا ٱلَّذِينَ كُنَّا نَدۡعُواْ مِن دُونِكَۖ فَأَلۡقَوۡاْ إِلَيۡهِمُ ٱلۡقَوۡلَ إِنَّكُمۡ لَكَٰذِبُونَ','اور جب مشرک (اپنے بنائے ہوئے) شریکوں کو دیکھیں گے تو کہیں گے کہ پروردگار یہ وہی ہمارے شریک ہیں جن کو ہم تیرے سوا پُکارا کرتے تھے۔ تو وہ (اُن کے کلام کو مسترد کردیں گے اور) اُن سے کہیں گے کہ تم تو جھوٹے ہو','And when the polytheists see their associate-gods, they will say, “Our Lord! These are our associate-gods that we used to invoke besides You.” Their gods will throw a rebuttal at them, ˹saying,˺ “You are definitely liars.”','और जिन लोगों ने दुनिया में ख़ुदा का शरीक (दूसरे को) ठहराया था जब अपने (उन) शरीकों को (क़यामत में) देखेंगे तो बोल उठेगें कि ऐ हमारे परवरदिगार यही तो हमारे शरीक हैं जिन्हें हम (मुसीबत) के वक्त तुझे छोड़ कर पुकारा करते थे तो वह शरीक उन्हीं की तरफ बात को फेंक मारेगें कि तुम निरे झूठे हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,87,'An-Nahl','وَأَلۡقَوۡاْ إِلَى ٱللَّهِ يَوۡمَئِذٍ ٱلسَّلَمَۖ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ','اور اس دن خدا کے سامنے سرنگوں ہو جائیں گے اور جو طوفان وہ باندھا کرتے تھے سب اُن سے جاتا رہے گا','They will offer ˹full˺ submission to Allah on that Day, and whatever ˹gods˺ they fabricated will fail them','और उस दिन ख़ुदा के सामने सर झुका देंगे और जो इफ़तेरा परदाज़ियाँ दुनिया में किया करते थे उनसे गायब हो जाएँगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,88,'An-Nahl','ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ زِدۡنَٰهُمۡ عَذَابࣰ ا فَوۡقَ ٱلۡعَذَابِ بِمَا كَانُواْ يُفۡسِدُونَ','جن لوگوں نے کفر کیا اور (لوگوں کو) خدا کے رستے سے روکا ہم اُن کو عذاب پر عذاب دیں گے۔ اس لیے کہ شرارت کیا کرتے تھے','For those who disbelieve and hinder ˹others˺ from the Way of Allah, We will add more punishment to their punishment for all the corruption they spread','जिन लोगों ने कुफ्र एख्तेयार किया और लोगों को ख़ुदा की राह से रोका उनके फ़साद वाले कामों के बदले में उनके लिए हम अज़ाब पर अज़ाब बढ़ाते जाएँगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,89,'An-Nahl','وَيَوۡمَ نَبۡعَثُ فِي كُلِّ أُمَّةࣲ شَهِيدًا عَلَيۡهِم مِّنۡ أَنفُسِهِمۡۖ وَجِئۡنَا بِكَ شَهِيدًا عَلَىٰ هَٰٓؤُلَآءِۚ وَنَزَّلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ تِبۡيَٰنࣰ ا لِّكُلِّ شَيۡءࣲ وَهُدࣰ ى وَرَحۡمَةࣰ وَبُشۡرَىٰ لِلۡمُسۡلِمِينَ','اور (اس دن کو یاد کرو) جس دن ہم ہر اُمت میں سے خود اُن پر گواہ کھڑے کریں گے۔ اور (اے پیغمبر) تم کو ان لوگوں پر گواہ لائیں گے۔ اور ہم نے تم پر (ایسی) کتاب نازل کی ہے کہ (اس میں) ہر چیز کا بیان (مفصل) ہے اور مسلمانوں کے لیے ہدایت اور رحمت اور بشارت ہے','˹Consider, O Prophet,˺ the Day We will call against every faith-community a witness of their own. And We will call you to be a witness against these ˹people of yours˺. We have revealed to you the Book as an explanation of all things, a guide, a mercy, and good news for those who ˹fully˺ submit','और वह दिन याद करो जिस दिन हम हर एक गिरोह में से उन्हीं में का एक गवाह उनके मुक़ाबिल ला खड़ा करेगें और (ऐ रसूल) तुम को उन लोगों पर (उनके) सामने गवाह बनाकर ला खड़ा करेंगें और हमने तुम पर किताब (क़ुरान) नाज़िल की जिसमें हर चीज़ का (शाफी) बयान है और मुसलमानों के लिए (सरमापा) हिदायत और रहमत और खुशख़बरी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,90,'An-Nahl','۞إِنَّ ٱللَّهَ يَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَٰنِ وَإِيتَآيِٕ ذِي ٱلۡقُرۡبَىٰ وَيَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِ وَٱلۡبَغۡيِۚ يَعِظُكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ','خدا تم کو انصاف اور احسان کرنے اور رشتہ داروں کو (خرچ سے مدد) دینے کا حکم دیتا ہے۔ اور بےحیائی اور نامعقول کاموں سے اور سرکشی سے منع کرتا ہے (اور) تمہیں نصیحت کرتا ہے تاکہ تم یاد رکھو','Indeed, Allah commands justice, grace, as well as courtesy to close relatives. He forbids indecency, wickedness, and aggression. He instructs you so perhaps you will be mindful','इसमें शक़ नहीं कि ख़ुदा इन्साफ और (लोगों के साथ) नेकी करने और क़राबतदारों को (कुछ) देने का हुक्म करता है और बदकारी और नाशाएस्ता हरकतों और सरकशी करने को मना करता है (और) तुम्हें नसीहत करता है ताकि तुम नसीहत हासिल करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,91,'An-Nahl','وَأَوۡفُواْ بِعَهۡدِ ٱللَّهِ إِذَا عَٰهَدتُّمۡ وَلَا تَنقُضُواْ ٱلۡأَيۡمَٰنَ بَعۡدَ تَوۡكِيدِهَا وَقَدۡ جَعَلۡتُمُ ٱللَّهَ عَلَيۡكُمۡ كَفِيلًاۚ إِنَّ ٱللَّهَ يَعۡلَمُ مَا تَفۡعَلُونَ','اور جب خدا سے عہد واثق کرو تو اس کو پورا کرو اور جب پکی قسمیں کھاؤ تو اُن کو مت توڑو کہ تم خدا کو اپنا ضامن مقرر کرچکے ہو۔ اور جو کچھ تم کرتے ہو خدا اس کو جانتا ہے','Honour Allah’s covenant when you make a pledge, and do not break your oaths after confirming them, having made Allah your guarantor. Surely Allah knows all you do','और जब तुम लोग बाहम क़ौल व क़रार कर लिया करो तो ख़ुदा के एहदो पैमान को पूरा करो और क़समों को उनके पक्का हो जाने के बाद न तोड़ा करो हालॉकि तुम तो ख़ुदा को अपना ज़ामिन बना चुके हो जो कुछ भी तुम करते हो ख़ुदा उसे ज़रुर जानता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,92,'An-Nahl','وَلَا تَكُونُواْ كَٱلَّتِي نَقَضَتۡ غَزۡلَهَا مِنۢ بَعۡدِ قُوَّةٍ أَنكَٰثࣰ ا تَتَّخِذُونَ أَيۡمَٰنَكُمۡ دَخَلَۢا بَيۡنَكُمۡ أَن تَكُونَ أُمَّةٌ هِيَ أَرۡبَىٰ مِنۡ أُمَّةٍۚ إِنَّمَا يَبۡلُوكُمُ ٱللَّهُ بِهِۦۚ وَلَيُبَيِّنَنَّ لَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ مَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ','اور اُس عورت کی طرح نہ ہونا جس نے محنت سے تو سوت کاتا۔ پھر اس کو توڑ کر ٹکڑے ٹکڑے کر ڈالا۔ کہ تم اپنی قسموں کو آپس میں اس بات کا ذریعہ بنانے لگو کہ ایک گروہ دوسرے گروہ سے زیادہ غالب رہے۔ بات یہ ہے کہ خدا تمہیں اس سے آزماتا ہے۔ اور جن باتوں میں تم اختلاف کرتے ہو قیامت کو اس کی حقیقت تم پر ظاہر کر دے گا','Do not be like the woman who ˹foolishly˺ unravels her yarn after it is firmly spun, by taking your oaths as a means of deceiving one another in favour of a stronger group. Surely Allah tests you through this. And on the Day of Judgment He will certainly make your differences clear to you','और तुम लोग (क़समों के तोड़ने में) उस औरत के ऐसे न हो जो अपना सूत मज़बूत कातने के बाद टुकड़े टुकड़े करके तोड़ डाले कि अपने एहदो को आपस में उस बात की मक्कारी का ज़रिया बनाने लगो कि एक गिरोह दूसरे गिरोह से (ख्वामख़वाह) बढ़ जाए इससे बस ख़ुदा तुमको आज़माता है (कि तुम किसी की पालाइश करते हो) और जिन बातों में तुम दुनिया में झगड़ते थे क़यामत के दिन ख़ुदा खुद तुम से साफ साफ बयान कर देगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,93,'An-Nahl','وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةࣰ وَٰحِدَةࣰ وَلَٰكِن يُضِلُّ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۚ وَلَتُسۡـَٔلُنَّ عَمَّا كُنتُمۡ تَعۡمَلُونَ','اور اگر خدا چاہتا تو تم (سب) کو ایک ہی جماعت بنا دیتا۔ لیکن وہ جسے چاہتا ہے گمراہ کرتا ہے اور جسے چاہتا ہے ہدایت دیتا ہے۔ اور جو عمل تم کرتے ہو (اُس دن) اُن کے بارے میں تم سے ضرور پوچھا جائے گا','Had Allah willed, He could have easily made you one community ˹of believers˺, but He leaves to stray whoever He wills and guides whoever He wills. And you will certainly be questioned about what you used to do','और अगर ख़ुदा चाहता तो तुम सबको एक ही (किस्म के) गिरोह बना देता मगर वह तो जिसको चाहता है गुमराही में छोड़ देता है और जिसकी चाहता है हिदायत करता है और जो कुछ तुम लोग दुनिया में किया करते थे उसकी बाज़ पुर्स (पुछ गछ) तुमसे ज़रुर की जाएगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,94,'An-Nahl','وَلَا تَتَّخِذُوٓاْ أَيۡمَٰنَكُمۡ دَخَلَۢا بَيۡنَكُمۡ فَتَزِلَّ قَدَمُۢ بَعۡدَ ثُبُوتِهَا وَتَذُوقُواْ ٱلسُّوٓءَ بِمَا صَدَدتُّمۡ عَن سَبِيلِ ٱللَّهِ وَلَكُمۡ عَذَابٌ عَظِيمࣱ‏','اور اپنی قسموں کو آپس میں اس بات کا ذریعہ نہ بناؤ کہ (لوگوں کے) قدم جم چکنے کے بعد لڑ کھڑا جائیں اور اس وجہ سے کہ تم نے لوگوں کو خدا کے رستے سے روکا تم کو عقوبت کا مزہ چکھنا پڑے۔ اور بڑا سخت عذاب ملے','And do not take your oaths as a means of deceiving one another or your feet will slip after they have been firm. Then you will taste the evil ˹consequences˺ of hindering ˹others˺ from the Way of Allah, and you will suffer a tremendous punishment','और तुम अपनी क़समों को आपस में के फसाद का सबब न बनाओ ताकि (लोगों के) क़दम जमने के बाद (इस्लाम से) उखड़ जाएँ और फिर आख़िरकार क़यामत में तुम्हें लोगों को ख़ुदा की राह से रोकने की पादाश (रोकने के बदले) में अज़ाब का मज़ा चखना पड़े और तुम्हारे वास्ते बड़ा सख्त अज़ाब हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,95,'An-Nahl','وَلَا تَشۡتَرُواْ بِعَهۡدِ ٱللَّهِ ثَمَنࣰ ا قَلِيلًاۚ إِنَّمَا عِندَ ٱللَّهِ هُوَ خَيۡرࣱ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ','اور خدا سے جو تم نے عہد کیا ہے (اس کو مت بیچو اور) اس کے بدلے تھوڑی سی قیمت نہ لو۔ (کیونکہ ایفائے عہد کا) جو صلہ خدا کے ہاں مقرر ہے وہ اگر سمجھو تو تمہارے لیے بہتر ہے','And do not trade Allah’s covenant for a fleeting gain. What is with Allah is certainly far better for you, if only you knew','और ख़ुदा के एहदो पैमान के बदले थोड़ी क़ीमत (दुनयावी नफा) न लो अगर तुम जानते (बूझते) हो तो (समझ लो कि) जो कुछ ख़ुदा के पास है वह उससे कहीं बेहतर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,96,'An-Nahl','مَا عِندَكُمۡ يَنفَدُ وَمَا عِندَ ٱللَّهِ بَاقࣲۗ وَلَنَجۡزِيَنَّ ٱلَّذِينَ صَبَرُوٓاْ أَجۡرَهُم بِأَحۡسَنِ مَا كَانُواْ يَعۡمَلُونَ','جو کچھ تمہارے پاس ہے وہ ختم ہو جاتا ہے اور جو خدا کے پاس ہے وہ باقی ہے کہ (کبھی ختم نہیں ہوگا) اور جن لوگوں نے صبر کیا ہم اُن کو ان کے اعمال کا بہت اچھا بدلہ دیں گے','Whatever you have will end, but whatever Allah has is everlasting. And We will certainly reward the steadfast according to the best of their deeds','(क्योंकि माल दुनिया से) जो कुछ तुम्हारे पास है एक न एक दिन ख़त्म हो जाएगा और (अज्र) ख़ुदा के पास है वह हमेशा बाक़ी रहेगा और जिन लोगों ने दुनिया में सब्र किया था उनको (क़यामत में) उनके कामों का हम अच्छे से अच्छा अज्र व सवाब अता करेंगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,97,'An-Nahl','مَنۡ عَمِلَ صَٰلِحࣰ ا مِّن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنࣱ فَلَنُحۡيِيَنَّهُۥ حَيَوٰةࣰ طَيِّبَةࣰۖ وَلَنَجۡزِيَنَّهُمۡ أَجۡرَهُم بِأَحۡسَنِ مَا كَانُواْ يَعۡمَلُونَ','جو شخص نیک اعمال کرے گا مرد ہو یا عورت وہ مومن بھی ہوگا تو ہم اس کو (دنیا میں) پاک (اور آرام کی) زندگی سے زندہ رکھیں گے اور (آخرت میں) اُن کے اعمال کا نہایت اچھا صلہ دیں گے','Whoever does good, whether male or female, and is a believer, We will surely bless them with a good life, and We will certainly reward them according to the best of their deeds','मर्द हो या औरत जो शख़्श नेक काम करेगा और वह ईमानदार भी हो तो हम उसे (दुनिया में भी) पाक व पाकीज़ा जिन्दगी बसर कराएँगें और (आख़िरत में भी) जो कुछ वह करते थे उसका अच्छे से अच्छा अज्र व सवाब अता फरमाएँगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,98,'An-Nahl','فَإِذَا قَرَأۡتَ ٱلۡقُرۡءَانَ فَٱسۡتَعِذۡ بِٱللَّهِ مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ','اور جب تم قرآن پڑھنے لگو تو شیطان مردود سے پناہ مانگ لیا کرو','When you recite the Quran, seek refuge with Allah from Satan, the accursed','और जब तुम क़ुरान पढ़ने लगो तो शैतान मरदूद (के वसवसो) से ख़ुदा की पनाह तलब कर लिया करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,99,'An-Nahl','إِنَّهُۥ لَيۡسَ لَهُۥ سُلۡطَٰنٌ عَلَى ٱلَّذِينَ ءَامَنُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ','کہ جو مومن ہیں اپنے پروردگار پر بھروسہ رکھتے ہیں اُن پر اس کا کچھ زور نہیں چلتا','He certainly has no authority over those who believe and put their trust in their Lord','इसमें शक नहीं कि जो लोग ईमानदार हैं और अपने परवरदिगार पर भरोसा रखते हैं उन पर उसका क़ाबू नहीं चलता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,100,'An-Nahl','إِنَّمَا سُلۡطَٰنُهُۥ عَلَى ٱلَّذِينَ يَتَوَلَّوۡنَهُۥ وَٱلَّذِينَ هُم بِهِۦ مُشۡرِكُونَ','اس کا زور ان ہی لوگوں پر چلتا ہے جو اس کو رفیق بناتے ہیں اور اس کے (وسوسے کے) سبب (خدا کے ساتھ) شریک مقرر کرتے ہیں','His authority is only over those who take him as a patron and who—under his influence—associate ˹others˺ with Allah ˹in worship˺','उसका क़ाबू चलता है तो बस उन्हीं लोगों पर जो उसको दोस्त बनाते हैं और जो लोग उसको ख़ुदा का शरीक बनाते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,101,'An-Nahl','وَإِذَا بَدَّلۡنَآ ءَايَةࣰ مَّكَانَ ءَايَةࣲ وَٱللَّهُ أَعۡلَمُ بِمَا يُنَزِّلُ قَالُوٓاْ إِنَّمَآ أَنتَ مُفۡتَرِۭۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ','اور جب ہم کوئی آیت کسی آیت کی جگہ بدل دیتے ہیں۔ اور خدا جو کچھ نازل فرماتا ہے اسے خوب جانتا ہے تو (کافر) کہتے ہیں کہ تم یونہی اپنی طرف سے بنا لاتے ہو۔ حقیقت یہ ہے کہ ان میں اکثر نادان ہیں','When We replace a verse with another—and Allah knows best what He reveals—they say, “You ˹Muḥammad˺ are just a fabricator.” In fact, most of them do not know','और (ऐ रसूल) हम जब एक आयत के बदले दूसरी आयत नाज़िल करते हैं तो हालॉकि ख़ुदा जो चीज़ नाज़िल करता है उस (की मसलहतों) से खूब वाक़िफ है मगर ये लोग (तुम को) कहने लगते हैं कि तुम बस बिल्कुल मुज़तरी (ग़लत बयान करने वाले) हो बल्कि खुद उनमें के बहुतेरे (मसालेह को) नहीं जानते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,102,'An-Nahl','قُلۡ نَزَّلَهُۥ رُوحُ ٱلۡقُدُسِ مِن رَّبِّكَ بِٱلۡحَقِّ لِيُثَبِّتَ ٱلَّذِينَ ءَامَنُواْ وَهُدࣰ ى وَبُشۡرَىٰ لِلۡمُسۡلِمِينَ','کہہ دو کہ اس کو روح القدس تمہارے پروردگار کی طرف سے سچائی کے ساتھ لے کر نازل ہوئے ہیں تاکہ یہ (قرآن) مومنوں کو ثابت قدم رکھے اور حکم ماننے والوں کے لئے تو (یہ) ہدایت اور بشارت ہے','Say, “The holy spirit has brought it down from your Lord with the truth to reassure the believers, and as a guide and good news for those who submit ˹to Allah˺.”','(ऐ रसूल) तुम (साफ) कह दो कि इस (क़ुरान) को तो रुहलकुदूस (जिबरील) ने तुम्हारे परवरदिगार की तरफ से हक़ नाज़िल किया है ताकि जो लोग ईमान ला चुके हैं उनको साबित क़दम रखे और मुसलमानों के लिए (अज़सरतापा) खुशखबरी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,103,'An-Nahl','وَلَقَدۡ نَعۡلَمُ أَنَّهُمۡ يَقُولُونَ إِنَّمَا يُعَلِّمُهُۥ بَشَرࣱۗ لِّسَانُ ٱلَّذِي يُلۡحِدُونَ إِلَيۡهِ أَعۡجَمِيࣱّ وَهَٰذَا لِسَانٌ عَرَبِيࣱّ مُّبِينٌ','اور ہمیں معلوم ہے کہ یہ کہتے ہیں کہ اس (پیغمبر) کو ایک شخص سکھا جاتا ہے۔ مگر جس کی طرف (تعلیم کی) نسبت کرتے ہیں اس کی زبان تو عجمی ہے اور یہ صاف عربی زبان ہے','And We surely know that they say, “No one is teaching him except a human.” But the man they refer to speaks a foreign tongue, whereas this ˹Quran˺ is ˹in˺ eloquent Arabic','और (ऐ रसूल) हम तहक़ीक़तन जानते हैं कि ये कुफ्फार तुम्हारी निस्बत कहा करते है कि उनको (तुम को) कोई आदमी क़ुरान सिखा दिया करता है हालॉकि बिल्कुल ग़लत है क्योंकि जिस शख्स की तरफ से ये लोग निस्बत देते हैं उसकी ज़बान तो अजमी है और ये तो साफ साफ अरबी ज़बान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,104,'An-Nahl','إِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِـَٔايَٰتِ ٱللَّهِ لَا يَهۡدِيهِمُ ٱللَّهُ وَلَهُمۡ عَذَابٌ أَلِيمٌ','یہ لوگ خدا کی آیتوں پر ایمان نہیں لاتے ان کو خدا ہدایت نہیں دیتا اور ان کے لئے عذاب الیم ہے','Surely those who do not believe in Allah’s revelations will never be guided by Allah, and they will suffer a painful punishment','इसमें तो शक ही नहीं कि जो लोग ख़ुदा की आयतों पर ईमान नहीं लाते ख़ुदा भी उनको मंज़िले मक़सूद तक नहीं पहुँचाएगा और उनके लिए दर्दनाक अज़ाब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,105,'An-Nahl','إِنَّمَا يَفۡتَرِي ٱلۡكَذِبَ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِـَٔايَٰتِ ٱللَّهِۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡكَٰذِبُونَ','جھوٹ افتراء تو وہی لوگ کیا کرتے ہیں جو خدا کی آیتوں پر ایمان نہیں لاتے۔ اور وہی جھوٹے ہیں','No one fabricates lies except those who disbelieve in Allah’s revelations, and it is they who are the ˹true˺ liars','झूठ बोहतान तो बस वही लोग बॉधा करते हैं जो खुदा की आयतों पर ईमान नहीं रखतें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,106,'An-Nahl','مَن كَفَرَ بِٱللَّهِ مِنۢ بَعۡدِ إِيمَٰنِهِۦٓ إِلَّا مَنۡ أُكۡرِهَ وَقَلۡبُهُۥ مُطۡمَئِنُّۢ بِٱلۡإِيمَٰنِ وَلَٰكِن مَّن شَرَحَ بِٱلۡكُفۡرِ صَدۡرࣰ ا فَعَلَيۡهِمۡ غَضَبࣱ مِّنَ ٱللَّهِ وَلَهُمۡ عَذَابٌ عَظِيمࣱ‏','جو شخص ایمان لانے کے بعد خدا کے ساتھ کفر کرے وہ نہیں جو (کفر پر زبردستی) مجبور کیا جائے اور اس کا دل ایمان کے ساتھ مطمئن ہو۔ بلکہ وہ جو (دل سے اور) دل کھول کر کفر کرے۔ تو ایسوں پر الله کا غضب ہے۔ اور ان کو بڑا سخت عذاب ہوگا','Whoever disbelieves in Allah after their belief—not those who are forced while their hearts are firm in faith, but those who embrace disbelief wholeheartedly—they will be condemned by Allah and suffer a tremendous punishment','और हक़ीक़त अम्र ये है कि यही लोग झूठे हैं उस शख्स के सिवा जो (कलमाए कुफ्र) पर मजबूर किया जाए और उसका दिल ईमान की तरफ से मुतमइन हो जो शख्स भी ईमान लाने के बाद कुफ्र एख्तियार करे बल्कि खूब सीना कुशादा (जी खोलकर) कुफ्र करे तो उन पर ख़ुदा का ग़ज़ब है और उनके लिए बड़ा (सख्त) अज़ाब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,107,'An-Nahl','ذَٰلِكَ بِأَنَّهُمُ ٱسۡتَحَبُّواْ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا عَلَى ٱلۡأٓخِرَةِ وَأَنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ','یہ اس لئے کہ انہوں نے دنیا کی زندگی کو آخرت کے مقابلے میں عزیز رکھا۔ اور اس لئے خدا کافر لوگوں کو ہدایت نہیں دیتا','This is because they prefer the life of this world over the Hereafter. Surely Allah never guides those who ˹choose to˺ disbelieve','ये इस वजह से कि उन लोगों ने दुनिया की चन्द रोज़ा ज़िन्दगी को आख़िरत पर तरजीह दी और इस वजह से की ख़ुदा काफिरों को हरगिज़ मंज़िले मक़सूद तक नहीं पहुँचाया करता');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,108,'An-Nahl','أُوْلَٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَسَمۡعِهِمۡ وَأَبۡصَٰرِهِمۡۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡغَٰفِلُونَ','یہی لوگ ہیں جن کے دلوں پر اور کانوں پر اور آنکھوں پر خدا نے مہر لگا رکھی ہے۔ اور یہی غفلت میں پڑے ہوئے ہیں','They are the ones whose hearts, ears, and eyes are sealed by Allah, and it is they who are ˹truly˺ heedless','ये वही लोग हैं जिनके दिलों पर और उनके कानों पर और उनकी ऑंखों पर खुदा ने अलामात मुक़र्रर कर दी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,109,'An-Nahl','لَا جَرَمَ أَنَّهُمۡ فِي ٱلۡأٓخِرَةِ هُمُ ٱلۡخَٰسِرُونَ','کچھ شک نہیں کہ یہ آخرت میں خسارہ اٹھانے والے ہوں گے','Without a doubt, they will be the losers in the Hereafter','(कि ईमान न लाएँगे) और यही लोग (इस सिरे के) बेखबर हैं कुछ शक़ नहीं कि यही लोग आख़िरत में भी यक़ीनन घाटा उठाने वाले हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,110,'An-Nahl','ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ هَاجَرُواْ مِنۢ بَعۡدِ مَا فُتِنُواْ ثُمَّ جَٰهَدُواْ وَصَبَرُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورࣱ رَّحِيمࣱ‏','پھر جن لوگوں نے ایذائیں اٹھانے کے بعد ترک وطن کیا۔ پھر جہاد کئے اور ثابت قدم رہے تمہارا پروردگار ان کو بےشک ان (آزمائشوں) کے بعد بخشنے والا (اور ان پر) رحمت کرنے والا ہے','As for those who emigrated after being compelled ˹to renounce Islam˺, then struggled ˹in Allah’s cause˺, and persevered, your Lord ˹O Prophet˺ is truly All-Forgiving, Most Merciful after all','फिर इसमें शक़ नहीं कि तुम्हारा परवरदिगार उन लोगों को जिन्होने मुसीबत में मुब्तिला होने क बाद घर बार छोडे फ़िर (ख़ुदा की राह में) जिहाद किए और तकलीफों पर सब्र किया इसमें शक़ नहीं कि तुम्हारा परवरदिगार इन सब बातों के बाद अलबत्ता बड़ा बख्शने वाला मेहरबान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,111,'An-Nahl','۞يَوۡمَ تَأۡتِي كُلُّ نَفۡسࣲ تُجَٰدِلُ عَن نَّفۡسِهَا وَتُوَفَّىٰ كُلُّ نَفۡسࣲ مَّا عَمِلَتۡ وَهُمۡ لَا يُظۡلَمُونَ','جس دن ہر متنفس اپنی طرف سے جھگڑا کرنے آئے گا۔ اور ہر شخص کو اس کے اعمال کا پورا پورا بدلہ دیا جائے گا۔ اور کسی کا نقصان نہیں کیا جائے گا','˹Consider˺ the Day ˹when˺ every soul will come pleading for itself, and each will be paid in full for what it did, and none will be wronged','और (उस दिन को याद) करो जिस दिन हर शख़्श अपनी ज़ात के बारे में झगड़ने को आ मौजूद होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,112,'An-Nahl','وَضَرَبَ ٱللَّهُ مَثَلࣰ ا قَرۡيَةࣰ كَانَتۡ ءَامِنَةࣰ مُّطۡمَئِنَّةࣰ يَأۡتِيهَا رِزۡقُهَا رَغَدࣰ ا مِّن كُلِّ مَكَانࣲ فَكَفَرَتۡ بِأَنۡعُمِ ٱللَّهِ فَأَذَٰقَهَا ٱللَّهُ لِبَاسَ ٱلۡجُوعِ وَٱلۡخَوۡفِ بِمَا كَانُواْ يَصۡنَعُونَ','اور خدا ایک بستی کی مثال بیان فرماتا ہے کہ (ہر طرح) امن چین سے بستی تھی ہر طرف سے رزق بافراغت چلا آتا تھا۔ مگر ان لوگوں نے خدا کی نعمتوں کی ناشکری کی تو خدا نے ان کے اعمال کے سبب ان کو بھوک اور خوف کا لباس پہنا کر (ناشکری کا) مزہ چکھا دیا','And Allah sets forth the example of a society which was safe and at ease, receiving its provision in abundance from all directions. But its people met Allah’s favours with ingratitude, so Allah made them taste the clutches of hunger and fear for their misdeeds','और हर शख़्श को जो कुछ भी उसने किया था उसका पूरा पूरा बदला मिलेगा और उन पर किसी तरह का जुल्म न किया जाएगा ख़ुदा ने एक गाँव की मसल बयान फरमाई जिसके रहने वाले हर तरह के चैन व इत्मेनान में थे हर तरफ से बाफराग़त (बहुत ज्यादा) उनकी रोज़ी उनके पास आई थी फिर उन लोगों ने ख़ुदा की नूअमतों की नाशुक्री की तो ख़ुदा ने उनकी करतूतों की बदौलत उनको मज़ा चखा दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,113,'An-Nahl','وَلَقَدۡ جَآءَهُمۡ رَسُولࣱ مِّنۡهُمۡ فَكَذَّبُوهُ فَأَخَذَهُمُ ٱلۡعَذَابُ وَهُمۡ ظَٰلِمُونَ','اور ان کے پاس ان ہی میں سے ایک پیغمبر آیا تو انہوں نے اس کو جھٹلایا سو ان کو عذاب نے آپکڑا اور وہ ظالم تھے','A messenger of their own actually did come to them, but they denied him. So the torment overtook them while they persisted in wrongdoing','कि भूक और ख़ौफ को ओढ़ना (बिछौना) बना दिया और उन्हीं लोगों में का एक रसूल भी उनके पास आया तो उन्होंने उसे झुठलाया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,114,'An-Nahl','فَكُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلࣰ ا طَيِّبࣰ ا وَٱشۡكُرُواْ نِعۡمَتَ ٱللَّهِ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ','پس خدا نے جو تم کو حلال طیّب رزق دیا ہے اسے کھاؤ۔ اور الله کی نعمتوں کا شکر کرو۔ اگر اسی کی عبادت کرتے ہو','So eat from the good, lawful things which Allah has provided for you, and be grateful for Allah’s favours, if you ˹truly˺ worship Him ˹alone˺','फिर अज़ाब (ख़ुदा) ने उन्हें ले डाला और वह ज़ालिम थे ही तो ख़ुदा ने जो कुछ तुम्हें हलाल तय्यब (ताहिर) रोज़ी दी है उसको (शौक़ से) खाओ और अगर तुम खुदा ही की परसतिश (का दावा करते हो)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,115,'An-Nahl','إِنَّمَا حَرَّمَ عَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦۖ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغࣲ وَلَا عَادࣲ فَإِنَّ ٱللَّهَ غَفُورࣱ رَّحِيمࣱ‏','اس نے تم پر مُردار اور لہو اور سور کا گوشت حرام کردیا ہے اور جس چیز پر خدا کے سوا کسی اور کا نام پکارا جائے (اس کو بھی) ہاں اگر کوئی ناچار ہوجائے تو بشرطیکہ گناہ کرنے والا نہ ہو اور نہ حد سے نکلنے والا تو خدا بخشنے والا مہربان ہے','He has only forbidden you ˹to eat˺ carrion, blood, swine, and what is slaughtered in the name of any other than Allah. But if someone is compelled by necessity—neither driven by desire nor exceeding immediate need—then surely Allah is All-Forgiving, Most Merciful','उसकी नेअमत का शुक्र अदा किया करो तुम पर उसने मुरदार और खून और सूअर का गोश्त और वह जानवर जिस पर (ज़बाह के वक्त) ख़ुदा के सिवा (किसी) और का नाम लिया जाए हराम किया है फिर जो शख़्श (मारे भूक के) मजबूर हो ख़ुदा से सरतापी (नाफरमानी) करने वाला हो और न (हद ज़रुरत से) बढ़ने वाला हो और (हराम खाए) तो बेशक ख़ुदा बख्शने वाला मेहरबान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,116,'An-Nahl','وَلَا تَقُولُواْ لِمَا تَصِفُ أَلۡسِنَتُكُمُ ٱلۡكَذِبَ هَٰذَا حَلَٰلࣱ وَهَٰذَا حَرَامࣱ لِّتَفۡتَرُواْ عَلَى ٱللَّهِ ٱلۡكَذِبَۚ إِنَّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ لَا يُفۡلِحُونَ','اور یوں ہی جھوٹ جو تمہاری زبان پر آجائے مت کہہ دیا کرو کہ یہ حلال ہے اور یہ حرام ہے کہ خدا پر جھوٹ بہتان باندھنے لگو۔ جو لوگ خدا پر جھوٹ بہتان باندھتے ہیں ان کا بھلا نہیں ہوگا','Do not falsely declare with your tongues, “This is lawful, and that is unlawful,” ˹only˺ fabricating lies against Allah. Indeed, those who fabricate lies against Allah will never succeed','और झूट मूट जो कुछ तुम्हारी ज़बान पर आए (बे समझे बूझे) न कह बैठा करों कि ये हलाल है और हराम है ताकि इसकी बदौलत ख़ुदा पर झूठ बोहतान बाँधने लगो इसमें शक़ नहीं कि जो लोग ख़ुदा पर झूठ बोहतान बाधते हैं वह कभी कामयाब न होगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,117,'An-Nahl','مَتَٰعࣱ قَلِيلࣱ وَلَهُمۡ عَذَابٌ أَلِيمࣱ‏','(جھوٹ کا) فائدہ تو تھوڑا سا ہے مگر (اس کے بدلے) ان کو عذاب الیم بہت ہوگا','˹It is only˺ a brief enjoyment, then they will suffer a painful punishment','(दुनिया में) फायदा तो ज़रा सा है और (आख़िरत में) दर्दनाक अज़ाब है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,118,'An-Nahl','وَعَلَى ٱلَّذِينَ هَادُواْ حَرَّمۡنَا مَا قَصَصۡنَا عَلَيۡكَ مِن قَبۡلُۖ وَمَا ظَلَمۡنَٰهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ','اور چیزیں ہم تم سے پہلے بیان کرچکے ہیں وہ ہم نے یہودیوں پر حرام کردی تھیں۔ اور ہم نے ان پر کچھ ظلم نہیں کیا بلکہ وہی اپنے آپ پر ظلم کرتے تھے','To the Jews, We have forbidden what We related to you before. We did not wrong them, but it was they who wronged themselves','और यहूदियों पर हमने वह चीज़े हराम कर दीं थी जो तुमसे पहले बयान कर चुके हैं और हमने तो (इस की वजह से) उन पर कुछ ज़ुल्म नहीं किया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,119,'An-Nahl','ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ عَمِلُواْ ٱلسُّوٓءَ بِجَهَٰلَةࣲ ثُمَّ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورࣱ رَّحِيمٌ','پھر جن لوگوں نے نادانی سے برا کام کیا۔ پھر اس کے بعد توبہ کی اور نیکوکار ہوگئے تو تمہارا پروردگار (ان کو) توبہ کرنے اور نیکوکار ہوجانے کے بعد بخشنے والا اور ان پر رحمت کرنے والا ہے','As for those who commit evil ignorantly ˹or recklessly˺, then repent afterwards and mend their ways, then your Lord is surely All-Forgiving, Most Merciful','मगर वह लोग खुद अपने ऊपर सितम तोड़ रहे हैं फिर इसमे शक़ नहीं कि जो लोग नादानी से गुनाह कर बैठे उसके बाद सदक़ दिल से तौबा कर ली और अपने को दुरुस्त कर लिया तो (ऐ रसूल) इसमें शक़ नहीं कि तुम्हारा परवरदिगार इसके बाद बख्शने वाला मेहरबान है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,120,'An-Nahl','إِنَّ إِبۡرَٰهِيمَ كَانَ أُمَّةࣰ قَانِتࣰ ا لِّلَّهِ حَنِيفࣰ ا وَلَمۡ يَكُ مِنَ ٱلۡمُشۡرِكِينَ','بےشک ابراہیم (لوگوں کے) امام اور خدا کے فرمانبردار تھے۔ جو ایک طرف کے ہو رہے تھے اور مشرکوں میں سے نہ تھے','Indeed, Abraham was a model of excellence: devoted to Allah, ˹perfectly˺ upright—not a polytheist—','इसमें शक़ नहीं कि इबराहीम (लोगों के) पेशवा ख़ुदा के फरमाबरदार बन्दे और बातिल से कतरा कर चलने वाले थे और मुशरेकीन से हरगिज़ न थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,121,'An-Nahl','شَاكِرࣰ ا لِّأَنۡعُمِهِۚ ٱجۡتَبَىٰهُ وَهَدَىٰهُ إِلَىٰ صِرَٰطࣲ مُّسۡتَقِيمࣲ‏','اس کی نعمتوں کے شکرگزار تھے۔ خدا نے ان کو برگزیدہ کیا تھا اور (اپنی) سیدھی راہ پر چلایا تھا','˹utterly˺ grateful for Allah’s favours. ˹So˺ He chose him and guided him to the Straight Path','उसकी नेअमतों के शुक्र गुज़ार उनको ख़ुदा ने मुनतख़िब कर लिया है और (अपनी) सीधी राह की उन्हें हिदायत की थी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,122,'An-Nahl','وَءَاتَيۡنَٰهُ فِي ٱلدُّنۡيَا حَسَنَةࣰۖ وَإِنَّهُۥ فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ','اور ہم نے ان کو دنیا میں بھی خوبی دی تھی۔ اور وہ آخرت میں بھی نیک لوگوں میں ہوں گے','We blessed him with all goodness in this world, and in the Hereafter he will certainly be among the righteous','और हमने उन्हें दुनिया में भी (हर तरह की) बेहतरी अता की थी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,123,'An-Nahl','ثُمَّ أَوۡحَيۡنَآ إِلَيۡكَ أَنِ ٱتَّبِعۡ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفࣰ اۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ','پھر ہم نے تمہاری طرف وحی بھیجی کہ دین ابراہیم کی پیروی اختیار کرو جو ایک طرف کے ہو رہے تھے اور مشرکوں میں سے نہ تھے','Then We revealed to you ˹O Prophet, saying˺: “Follow the faith of Abraham, the upright, who was not one of the polytheists.”','और वह आख़िरत में भी यक़ीनन नेको कारों से होगें ऐ रसूल फिर तुम्हारे पास वही भेजी कि इबराहीम के तरीक़े की पैरवी करो जो बातिल से कतरा के चलते थे और मुशरेकीन से नहीं थे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,124,'An-Nahl','إِنَّمَا جُعِلَ ٱلسَّبۡتُ عَلَى ٱلَّذِينَ ٱخۡتَلَفُواْ فِيهِۚ وَإِنَّ رَبَّكَ لَيَحۡكُمُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ','ہفتے کا دن تو ان ہی لوگوں کے لئے مقرر کیا گیا تھا۔ جنہوں نے اس میں اختلاف کیا۔ اور تمہارا پروردگار قیامت کے دن ان میں ان باتوں کا فیصلہ کردے گا جن میں وہ اختلاف کرتے تھے','˹Honouring˺ the Sabbath was ordained only for those who disputed about Abraham. And surely your Lord will judge between them on the Day of Judgment regarding their disputes','(ऐ रसूल) हफ्ते (के दिन) की ताज़ीम तो बस उन्हीं लोगों पर लाज़िम की गई थी (यहूद व नसारा इसके बारे में) एख्तिलाफ करते थे और कुछ शक़ नहीं कि तुम्हारा परवरदिगार उनके दरमियान जिस अग्र में वह झगड़ा करते थे क़यामत के दिन फैसला कर देगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,125,'An-Nahl','ٱدۡعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلۡحِكۡمَةِ وَٱلۡمَوۡعِظَةِ ٱلۡحَسَنَةِۖ وَجَٰدِلۡهُم بِٱلَّتِي هِيَ أَحۡسَنُۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ','(اے پیغمبر) لوگوں کو دانش اور نیک نصیحت سے اپنے پروردگار کے رستے کی طرف بلاؤ۔ اور بہت ہی اچھے طریق سے ان سے مناظرہ کرو۔ جو اس کے رستے سے بھٹک گیا تمہارا پروردگار اسے بھی خوب جانتا ہے اور جو رستے پر چلنے والے ہیں ان سے بھی خوب واقف ہے','Invite ˹all˺ to the Way of your Lord with wisdom and kind advice, and only debate with them in the best manner. Surely your Lord ˹alone˺ knows best who has strayed from His Way and who is ˹rightly˺ guided','(ऐ रसूल) तुम (लोगों को) अपने परवरदिगार की राह पर हिकमत और अच्छी अच्छी नसीहत के ज़रिए से बुलाओ और बहस व मुबाशा करो भी तो इस तरीक़े से जो लोगों के नज़दीक सबसे अच्छा हो इसमें शक़ नहीं कि जो लोग ख़ुदा की राह से भटक गए उनको तुम्हारा परवरदिगार खूब जानता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,126,'An-Nahl','وَإِنۡ عَاقَبۡتُمۡ فَعَاقِبُواْ بِمِثۡلِ مَا عُوقِبۡتُم بِهِۦۖ وَلَئِن صَبَرۡتُمۡ لَهُوَ خَيۡرࣱ لِّلصَّٰبِرِينَ','اور اگر تم ان کو تکلیف دینی چاہو تو اتنی ہی دو جتنی تکلیف تم کو ان سے پہنچی۔ اور اگر صبر کرو تو وہ صبر کرنے والوں کے لیے بہت اچھا ہے','If you retaliate, then let it be equivalent to what you have suffered. But if you patiently endure, it is certainly best for those who are patient','और हिदायत याफ़ता लोगों से भी खूब वाक़िफ है और अगर (मुख़ालिफीन के साथ) सख्ती करो भी तो वैसी ही सख्ती करो जैसे सख्ती उन लोगों ने तुम पर की थी और अगर तुम सब्र करो तो सब्र करने वालों के वास्ते बेहतर हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,127,'An-Nahl','وَٱصۡبِرۡ وَمَا صَبۡرُكَ إِلَّا بِٱللَّهِۚ وَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَلَا تَكُ فِي ضَيۡقࣲ مِّمَّا يَمۡكُرُونَ','اور صبر ہی کرو اور تمہارا صبر بھی خدا ہی کی مدد سے ہے اور ان کے بارے میں غم نہ کرو اور جو یہ بداندیشی کرتے ہیں اس سے تنگدل نہ ہو','Be patient ˹O Prophet˺, for your patience is only with Allah’s help. Do not grieve over those ˹who disbelieve˺, nor be distressed by their schemes','और (ऐ रसूल) तुम सब्र ही करो (और ख़ुदा की (मदद) बग़ैर तो तुम सब्र कर भी नहीं सकते और उन मुख़ालिफीन के हाल पर तुम रंज न करो और जो मक्कारीयाँ ये लोग करते हैं उससे तुम तंग दिल न हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (16,128,'An-Nahl','إِنَّ ٱللَّهَ مَعَ ٱلَّذِينَ ٱتَّقَواْ وَّٱلَّذِينَ هُم مُّحۡسِنُونَ','کچھ شک نہیں کہ جو پرہیزگار ہیں اور جو نیکوکار ہیں خدا ان کا مددگار ہے','Surely Allah is with those who shun evil and who do good ˹deeds˺','जो लोग परहेज़गार हैं और जो लोग नेको कार हैं ख़ुदा उनका साथी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,1,'Al-Israa','سُبۡحَٰنَ ٱلَّذِيٓ أَسۡرَىٰ بِعَبۡدِهِۦ لَيۡلࣰ ا مِّنَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ إِلَى ٱلۡمَسۡجِدِ ٱلۡأَقۡصَا ٱلَّذِي بَٰرَكۡنَا حَوۡلَهُۥ لِنُرِيَهُۥ مِنۡ ءَايَٰتِنَآۚ إِنَّهُۥ هُوَ ٱلسَّمِيعُ ٱلۡبَصِيرُ','وہ (ذات) پاک ہے جو ایک رات اپنے بندے کو مسجدالحرام یعنی (خانہٴ کعبہ) سے مسجد اقصیٰ (یعنی بیت المقدس) تک جس کے گردا گرد ہم نے برکتیں رکھی ہیں لے گیا تاکہ ہم اسے اپنی (قدرت کی) نشانیاں دکھائیں۔ بےشک وہ سننے والا (اور) دیکھنے والا ہے','Glory be to the One Who took His servant ˹Muḥammad˺ by night from the Sacred Mosque to the Farthest Mosque whose surroundings We have blessed, so that We may show him some of Our signs. Indeed, He alone is the All-Hearing, All-Seeing','वह ख़ुदा (हर ऐब से) पाक व पाकीज़ा है जिसने अपने बन्दों को रातों रात मस्जिदुल हराम (ख़ान ऐ काबा) से मस्जिदुल अक़सा (आसमानी मस्जिद) तक की सैर कराई जिसके चौगिर्द हमने हर किस्म की बरकत मुहय्या कर रखी हैं ताकि हम उसको (अपनी कुदरत की) निशानियाँ दिखाए इसमें शक़ नहीं कि (वह सब कुछ) सुनता (और) देखता है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,2,'Al-Israa','وَءَاتَيۡنَا مُوسَى ٱلۡكِتَٰبَ وَجَعَلۡنَٰهُ هُدࣰ ى لِّبَنِيٓ إِسۡرَٰٓءِيلَ أَلَّا تَتَّخِذُواْ مِن دُونِي وَكِيلࣰ ا','اور ہم نے موسیٰ کو کتاب عنایت کی تھی اور اس کو بنی اسرائیل کے لئے رہنما مقرر کیا تھا کہ میرے سوا کسی کو کارساز نہ ٹھہرانا','And We gave Moses the Scripture and made it a guide for the Children of Israel, ˹stating:˺ “Do not take besides Me any other Trustee of Affairs','और हमने मूसा को किताब (तौरैत) अता की और उस को बनी इसराईल की रहनुमा क़रार दिया (और हुक्म दे दिया) कि ऐ उन लोगों की औलाद जिन्हें हम ने नूह के साथ कश्ती में सवार किया था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,3,'Al-Israa','ذُرِّيَّةَ مَنۡ حَمَلۡنَا مَعَ نُوحٍۚ إِنَّهُۥ كَانَ عَبۡدࣰ ا شَكُورࣰ ا','اے اُن لوگوں کی اولاد جن کو ہم نے نوح کے ساتھ (کشتی میں) سوار کیا تھا۔ بےشک نوح (ہمارے) شکرگزار بندے تھے','˹O˺ descendants of those We carried with Noah ˹in the Ark˺! He was indeed a grateful servant.”','मेरे सिवा किसी को अपना कारसाज़ न बनाना बेशक नूह बड़ा शुक्र गुज़ार बन्दा था');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,4,'Al-Israa','وَقَضَيۡنَآ إِلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ فِي ٱلۡكِتَٰبِ لَتُفۡسِدُنَّ فِي ٱلۡأَرۡضِ مَرَّتَيۡنِ وَلَتَعۡلُنَّ عُلُوࣰّ ا كَبِيرࣰ ا','اور ہم نے کتاب میں بنی اسرائیل سے کہہ دیا تھا کہ زمین میں دو دفعہ فساد مچاؤ گے اور بڑی سرکشی کرو گے','And We warned the Children of Israel in the Scripture, “You will certainly cause corruption in the land twice, and you will become extremely arrogant','और हमने बनी इसराईल से इसी किताब (तौरैत) में साफ साफ बयान कर दिया था कि तुम लोग रुए ज़मीन पर दो मरतबा ज़रुर फसाद फैलाओगे और बड़ी सरकशी करोगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,5,'Al-Israa','فَإِذَا جَآءَ وَعۡدُ أُولَىٰهُمَا بَعَثۡنَا عَلَيۡكُمۡ عِبَادࣰ ا لَّنَآ أُوْلِي بَأۡسࣲ شَدِيدࣲ فَجَاسُواْ خِلَٰلَ ٱلدِّيَارِۚ وَكَانَ وَعۡدࣰ ا مَّفۡعُولࣰ ا','پس جب پہلے (وعدے) کا وقت آیا تو ہم نے سخت لڑائی لڑنے والے بندے تم پر مسلط کردیئے اور وہ شہروں کے اندر پھیل گئے۔ اور وہ وعدہ پورا ہو کر رہا','When the first of the two warnings would come to pass, We would send against you some of Our servants of great might, who would ravage your homes. This would be a warning fulfilled','फिर जब उन दो फसादों में पहले का वक्त अा पहुँचा तो हमने तुम पर कुछ अपने बन्दों (नजतुलनस्र) और उसकी फौज को मुसल्लत (ग़ालिब) कर दिया जो बड़े सख्त लड़ने वाले थे तो वह लोग तुम्हारे घरों के अन्दर घुसे (और खूब क़त्ल व ग़ारत किया) और ख़ुदा के अज़ाब का वायदा जो पूरा होकर रहा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,6,'Al-Israa','ثُمَّ رَدَدۡنَا لَكُمُ ٱلۡكَرَّةَ عَلَيۡهِمۡ وَأَمۡدَدۡنَٰكُم بِأَمۡوَٰلࣲ وَبَنِينَ وَجَعَلۡنَٰكُمۡ أَكۡثَرَ نَفِيرًا','پھر ہم نے دوسری بات تم کو اُن پر غلبہ دیا اور مال اور بیٹوں سے تمہاری مدد کی۔ اور تم کو جماعت کثیر بنا دیا','Then ˹after your repentance˺ We would give you the upper hand over them and aid you with wealth and offspring, causing you to outnumber them','फिर हमने तुमको दोबारा उन पर ग़लबा देकर तुम्हारे दिन फेरे और माल से और बेटों से तुम्हारी मदद की और तुमको बड़े जत्थे वाला बना दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,7,'Al-Israa','إِنۡ أَحۡسَنتُمۡ أَحۡسَنتُمۡ لِأَنفُسِكُمۡۖ وَإِنۡ أَسَأۡتُمۡ فَلَهَاۚ فَإِذَا جَآءَ وَعۡدُ ٱلۡأٓخِرَةِ لِيَسُـُٔواْ وُجُوهَكُمۡ وَلِيَدۡخُلُواْ ٱلۡمَسۡجِدَ كَمَا دَخَلُوهُ أَوَّلَ مَرَّةࣲ وَلِيُتَبِّرُواْ مَا عَلَوۡاْ تَتۡبِيرًا','اگر تم نیکوکاری کرو گے تو اپنی جانوں کے لئے کرو گے۔ اور اگر اعمال بد کرو گے تو (اُن کا) وبال بھی تمہاری ہی جانوں پر ہوگا پھر جب دوسرے (وعدے) کا وقت آیا (تو ہم نے پھر اپنے بندے بھیجے) تاکہ تمہارے چہروں کو بگاڑ دیں اور جس طرح پہلی دفعہ مسجد (بیت المقدس) میں داخل ہوگئے تھے اسی طرح پھر اس میں داخل ہوجائیں اور جس چیز پر غلبہ پائیں اُسے تباہ کردیں','If you act rightly, it is for your own good, but if you do wrong, it is to your own loss. “And when the second warning would come to pass, your enemies would ˹be left to˺ totally disgrace you and enter the Temple ˹of Jerusalem˺ as they entered it the first time, and utterly destroy whatever would fall into their hands','अगर तुम अच्छे काम करोगे तो अपने फायदे के लिए अच्छे काम करोगे और अगर तुम बुरे काम करोगे तो (भी) अपने ही लिए फिर जब दूसरे वक्त क़ा वायदा आ पहुँचा तो (हमने तैतूस रोगी को तुम पर मुसल्लत किया) ताकि वह लोग (मारते मारते) तुम्हारे चेहरे बिगाड़ दें (कि पहचाने न जाओ) और जिस तरह पहली दफा मस्जिद बैतुल मुक़द्दस में घुस गये थे उसी तरह फिर घुस पड़ें और जिस चीज़ पर क़ाबू पाए खूब अच्छी तरह बरबाद कर दी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,8,'Al-Israa','عَسَىٰ رَبُّكُمۡ أَن يَرۡحَمَكُمۡۚ وَإِنۡ عُدتُّمۡ عُدۡنَاۚ وَجَعَلۡنَا جَهَنَّمَ لِلۡكَٰفِرِينَ حَصِيرًا','امید ہے کہ تمہارا پروردگار تم پر رحم کرے، اور اگر تم پھر وہی (حرکتیں) کرو گے تو ہم بھی (وہی پہلا سلوک) کریں گے اور ہم نے جہنم کو کافروں کے لئے قید خانہ بنا رکھا ہے','Perhaps your Lord will have mercy on you ˹if you repent˺, but if you return ˹to sin˺, We will return ˹to punishment˺. And We have made Hell a ˹permanent˺ confinement for the disbelievers.”','(अब भी अगर तुम चैन से रहो तो) उम्मीद है कि तुम्हारा परवरदिगार तुम पर तरस खाए और अगर (कहीं) वही शरारत करोगे तो हम भी फिर पकड़ेंगे और हमने तो काफिरों के लिए जहन्नुम को क़ैद खाना बना ही रखा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,9,'Al-Israa','إِنَّ هَٰذَا ٱلۡقُرۡءَانَ يَهۡدِي لِلَّتِي هِيَ أَقۡوَمُ وَيُبَشِّرُ ٱلۡمُؤۡمِنِينَ ٱلَّذِينَ يَعۡمَلُونَ ٱلصَّٰلِحَٰتِ أَنَّ لَهُمۡ أَجۡرࣰ ا كَبِيرࣰ ا','یہ قرآن وہ رستہ دکھاتا ہے جو سب سے سیدھا ہے اور مومنوں کو جو نیک عمل کرتے ہیں بشارت دیتا ہے کہ اُن کے لئے اجر عظیم ہے','Surely this Quran guides to what is most upright, and gives good news to the believers—who do good—that they will have a mighty reward','इसमें शक़ नहीं कि ये क़ुरान उस राह की हिदायत करता है जो सबसे ज्यादा सीधी है और जो ईमानदार अच्छे अच्छे काम करते हैं उनको ये खुशख़बरी देता है कि उनके लिए बहुत बड़ा अज्र और सवाब (मौजूद) है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,10,'Al-Israa','وَأَنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ أَعۡتَدۡنَا لَهُمۡ عَذَابًا أَلِيمࣰ ا','اور یہ بھی (بتاتا ہے) کہ جو آخرت پر ایمان نہیں رکھتے اُن کے لئے ہم نے دکھ دینے والا عذاب تیار کر رکھا ہے','And ˹it warns˺ those who do not believe in the Hereafter ˹that˺ We have prepared for them a painful punishment','और ये भी कि बेशक जो लोग आख़िरत पर ईमान नहीं रखते हैं उनके लिए हमने दर्दनाक अज़ाब तैयार कर रखा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,11,'Al-Israa','وَيَدۡعُ ٱلۡإِنسَٰنُ بِٱلشَّرِّ دُعَآءَهُۥ بِٱلۡخَيۡرِۖ وَكَانَ ٱلۡإِنسَٰنُ عَجُولࣰ ا','اور انسان جس طرح (جلدی سے) بھلائی مانگتا ہے اسی طرح برائی مانگتا ہے۔ اور انسان جلد باز (پیدا ہوا) ہے','And humans ˹swiftly˺ pray for evil as they pray for good. For humankind is ever hasty','और आदमी कभी (आजिज़ होकर अपने हक़ में) बुराई (अज़ाब वग़ैरह की दुआ) इस तरह माँगता है जिस तरह अपने लिए भलाई की दुआ करता है और आदमी तो बड़ा जल्दबाज़ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,12,'Al-Israa','وَجَعَلۡنَا ٱلَّيۡلَ وَٱلنَّهَارَ ءَايَتَيۡنِۖ فَمَحَوۡنَآ ءَايَةَ ٱلَّيۡلِ وَجَعَلۡنَآ ءَايَةَ ٱلنَّهَارِ مُبۡصِرَةࣰ لِّتَبۡتَغُواْ فَضۡلࣰ ا مِّن رَّبِّكُمۡ وَلِتَعۡلَمُواْ عَدَدَ ٱلسِّنِينَ وَٱلۡحِسَابَۚ وَكُلَّ شَيۡءࣲ فَصَّلۡنَٰهُ تَفۡصِيلࣰ ا','اور ہم نے دن اور رات کو دو نشانیاں بنایا ہے رات کی نشانی کو تاریک بنایا اور دن کی نشانی کو روشن۔ تاکہ تم اپنے پروردگار کا فضل (یعنی) روزی تلاش کرو اور برسوں کا شمار اور حساب جانو۔ اور ہم نے ہر چیز کو (بخوبی) تفصیل کردی ہے','We made the day and night as two signs. So We made the sign of the night devoid of light, and We made the sign of the day ˹perfectly˺ bright, so that you may seek the bounty of your Lord and know the number of years and calculation ˹of time˺. And We have explained everything in detail','और हमने रात और दिन को (अपनी क़ुदरत की) दो निशानियाँ क़रार दिया फिर हमने रात की निशानी (चाँद) को धुँधला बनाया और दिन की निशानी (सूरज) को रौशन बनाया (कि सब चीज़े दिखाई दें) ताकि तुम लोग अपने परवरदिगार का फज़ल ढूँढते फिरों और ताकि तुम बरसों की गिनती और हिसाब को जानो (बूझों) और हमने हर चीज़ को खूब अच्छी तरह तफसील से बयान कर दिया है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,13,'Al-Israa','وَكُلَّ إِنسَٰنٍ أَلۡزَمۡنَٰهُ طَٰٓئِرَهُۥ فِي عُنُقِهِۦۖ وَنُخۡرِجُ لَهُۥ يَوۡمَ ٱلۡقِيَٰمَةِ كِتَٰبࣰ ا يَلۡقَىٰهُ مَنشُورًا','اور ہم نے ہر انسان کے اعمال کو (بہ صورت کتاب) اس کے گلے میں لٹکا دیا ہے۔ اور قیامت کے روز (وہ) کتاب اسے نکال دکھائیں گے جسے وہ کھلا ہوا دیکھے گا','We have bound every human’s destiny to their neck. And on the Day of Judgment We will bring forth to each ˹person˺ a record which they will find laid open','और हमने हर आदमी के नामए अमल को उसके गले का हार बना दिया है (कि उसकी किस्मत उसके साथ रहे) और क़यामत के दिन हम उसे उसके सामने निकल के रख देगें कि वह उसको एक खुली हुई किताब अपने रुबरु पाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,14,'Al-Israa','ٱقۡرَأۡ كِتَٰبَكَ كَفَىٰ بِنَفۡسِكَ ٱلۡيَوۡمَ عَلَيۡكَ حَسِيبࣰ ا','(کہا جائے گا کہ) اپنی کتاب پڑھ لے۔ تو آج اپنا آپ ہی محاسب کافی ہے','˹And it will be said,˺ “Read your record. You ˹alone˺ are sufficient this Day to take account of yourself.”','और हम उससे कहेंगें कि अपना नामए अमल पढ़ले और आज अपने हिसाब के लिए तू आप ही काफी हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,15,'Al-Israa','مَّنِ ٱهۡتَدَىٰ فَإِنَّمَا يَهۡتَدِي لِنَفۡسِهِۦۖ وَمَن ضَلَّ فَإِنَّمَا يَضِلُّ عَلَيۡهَاۚ وَلَا تَزِرُ وَازِرَةࣱ وِزۡرَ أُخۡرَىٰۗ وَمَا كُنَّا مُعَذِّبِينَ حَتَّىٰ نَبۡعَثَ رَسُولࣰ ا','جو شخص ہدایت اختیار کرتا ہے تو اپنے لئے اختیار کرتا ہے۔ اور جو گمراہ ہوتا ہے گمراہی کا ضرر بھی اسی کو ہوگا۔ اور کوئی شخص کسی دوسرے کا بوجھ نہیں اٹھائے گا۔ اور جب تک ہم پیغمبر نہ بھیج لیں عذاب نہیں دیا کرتے','Whoever chooses to be guided, it is only for their own good. And whoever chooses to stray, it is only to their own loss. No soul burdened with sin will bear the burden of another. And We would never punish ˹a people˺ until We have sent a messenger ˹to warn them˺','जो शख़्श रुबरु होता है तो बस अपने फायदे के लिए यह पर आता है और जो शख़्श गुमराह होता है तो उसने भटक कर अपना आप बिगाड़ा और कोई शख़्श किसी दूसरे (के गुनाह) का बोझ अपने सर नहीं लेगा और हम तो जब तक रसूल को भेजकर तमाम हुज्जत न कर लें किसी पर अज़ाब नहीं किया करते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,16,'Al-Israa','وَإِذَآ أَرَدۡنَآ أَن نُّهۡلِكَ قَرۡيَةً أَمَرۡنَا مُتۡرَفِيهَا فَفَسَقُواْ فِيهَا فَحَقَّ عَلَيۡهَا ٱلۡقَوۡلُ فَدَمَّرۡنَٰهَا تَدۡمِيرࣰ ا','اور جب ہمارا ارادہ کسی بستی کے ہلاک کرنے کا ہوا تو وہاں کے آسودہ لوگوں کو (فواحش پر) مامور کردیا تو وہ نافرمانیاں کرتے رہے۔ پھر اس پر (عذاب کا) حکم ثابت ہوگیا۔ اور ہم نے اسے ہلاک کر ڈالا','Whenever We intend to destroy a society, We command its elite ˹to obey Allah˺ but they act rebelliously in it. So the decree ˹of punishment˺ is justified, and We destroy it utterly','और हमको जब किसी बस्ती का वीरान करना मंज़ूर होता है तो हम वहाँ के खुशहालों को (इताअत का) हुक्म देते हैं तो वह लोग उसमें नाफरमानियाँ करने लगे तब वह बस्ती अज़ाब की मुस्तहक़ होगी उस वक्त हमने उसे अच्छी तरह तबाह व बरबाद कर दिया');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,17,'Al-Israa','وَكَمۡ أَهۡلَكۡنَا مِنَ ٱلۡقُرُونِ مِنۢ بَعۡدِ نُوحࣲۗ وَكَفَىٰ بِرَبِّكَ بِذُنُوبِ عِبَادِهِۦ خَبِيرَۢا بَصِيرࣰ ا','اور ہم نے نوح کے بعد بہت سی اُمتوں کو ہلاک کر ڈالا۔ اور تمہارا پروردگار اپنے بندوں کے گناہوں کو جاننے اور دیکھنے والا کافی ہے','˹Imagine˺ how many peoples We have destroyed after Noah! And sufficient is your Lord as All-Aware and All-Seeing of the sins of His servants','और नूह के बाद से (उस वक्त तक) हमने कितनी उम्मतों को हलाक कर मारा और (ऐ रसूल) तुम्हारा परवरदिगार अपने बन्दों के गुनाहों को जानने और देखने के लिए काफी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,18,'Al-Israa','مَّن كَانَ يُرِيدُ ٱلۡعَاجِلَةَ عَجَّلۡنَا لَهُۥ فِيهَا مَا نَشَآءُ لِمَن نُّرِيدُ ثُمَّ جَعَلۡنَا لَهُۥ جَهَنَّمَ يَصۡلَىٰهَا مَذۡمُومࣰ ا مَّدۡحُورࣰ ا','جو شخص دنیا (کی آسودگی) کا خواہشمند ہو تو ہم اس میں سے جسے چاہتے ہیں اور جتنا چاہتے ہیں جلد دے دیتے ہیں۔ پھر اس کے لئے جہنم کو (ٹھکانا) مقرر کر رکھا ہے۔ جس میں وہ نفرین سن کر اور (درگاہ خدا سے) راندہ ہو کر داخل ہوگا','Whoever desires this fleeting world ˹alone˺, We hasten in it whatever We please to whoever We will; then We destine them for Hell, where they will burn, condemned and rejected','(और गवाह याहिद की ज़रुरत नहीं) और जो शख़्श दुनिया का ख्वाहाँ हो तो हम जिसे चाहते और जो चाहते हैं उसी दुनिया में सिरदस्त (फ़ौरन) उसे अता करते हैं (मगर) फिर हमने उसके लिए तो जहन्नुम ठहरा ही रखा है कि वह उसमें बुरी हालत से रौंदा हुआ दाख़िल होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,19,'Al-Israa','وَمَنۡ أَرَادَ ٱلۡأٓخِرَةَ وَسَعَىٰ لَهَا سَعۡيَهَا وَهُوَ مُؤۡمِنࣱ فَأُوْلَٰٓئِكَ كَانَ سَعۡيُهُم مَّشۡكُورࣰ ا','اور جو شخص آخرت کا خواستگار ہوا اور اس میں اتنی کوشش کرے جتنی اسے لائق ہے اور وہ مومن بھی ہو تو ایسے ہی لوگوں کی کوشش ٹھکانے لگتی ہے','But whoever desires the Hereafter and strives for it accordingly, and is a ˹true˺ believer, it is they whose striving will be appreciated','और जो शख़्श आख़िर का मुतमइनी हो और उसके लिए खूब जैसी चाहिए कोशिश भी की और वह ईमानदार भी है तो यही वह लोग हैं जिनकी कोशिश मक़बूल होगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,20,'Al-Israa','كُلࣰّ ا نُّمِدُّ هَٰٓؤُلَآءِ وَهَٰٓؤُلَآءِ مِنۡ عَطَآءِ رَبِّكَۚ وَمَا كَانَ عَطَآءُ رَبِّكَ مَحۡظُورًا','ہم اُن کو اور ان کو سب کو تمہارے پروردگار کی بخشش سے مدد دیتے ہیں۔ اور تمہارے پروردگار کی بخشش (کسی سے) رکی ہوئی نہیں','We provide both the former and the latter from the bounty of your Lord. And the bounty of your Lord can never be withheld','(ऐ रसूल) उनको (ग़रज़ सबको) हम ही तुम्हारे परवरदिगार की (अपनी) बख़्शिस से मदद देते हैं और तुम्हारे परवरदिगार की बख़्शिस तो (आम है) किसी पर बन्द नहीं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,21,'Al-Israa','ٱنظُرۡ كَيۡفَ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضࣲۚ وَلَلۡأٓخِرَةُ أَكۡبَرُ دَرَجَٰتࣲ وَأَكۡبَرُ تَفۡضِيلࣰ ا','دیکھو ہم نے کس طرح بعض کو بعض پر فضیلت بخشی ہے۔ اور آخرت درجوں میں (دنیا سے) بہت برتر اور برتری میں کہیں بڑھ کر ہے','See how We have favoured some over others ˹in this life˺, but the Hereafter is certainly far greater in rank and in favour','(ऐ रसूल) ज़रा देखो तो कि हमने बाज़ लोगों को बाज़ पर कैसी फज़ीलत दी है और आख़िरत के दर्जे तो यक़ीनन (यहाँ से) कहीं बढ़के है और वहाँ की फज़ीलत भी तो कैसी बढ़ कर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,22,'Al-Israa','لَّا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتَقۡعُدَ مَذۡمُومࣰ ا مَّخۡذُولࣰ ا','اور خدا کے ساتھ کوئی اور معبود نہ بنانا کہ ملامتیں سن کر اور بےکس ہو کر بیٹھے رہ جاؤ گے','Do not set up any other god with Allah, or you will end up condemned, abandoned','और देखो कहीं ख़ुदा के साथ दूसरे को (उसका) शरीक न बनाना वरना तुम बुरे हाल में ज़लील रुसवा बैठै के बैठें रह जाओगे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,23,'Al-Israa','۞وَقَضَىٰ رَبُّكَ أَلَّا تَعۡبُدُوٓاْ إِلَّآ إِيَّاهُ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنًاۚ إِمَّا يَبۡلُغَنَّ عِندَكَ ٱلۡكِبَرَ أَحَدُهُمَآ أَوۡ كِلَاهُمَا فَلَا تَقُل لَّهُمَآ أُفࣲّ وَلَا تَنۡهَرۡهُمَا وَقُل لَّهُمَا قَوۡلࣰ ا كَرِيمࣰ ا','اور تمہارے پروردگار نے ارشاد فرمایا ہے کہ اس کے سوا کسی کی عبادت نہ کرو اور ماں باپ کے ساتھ بھلائی کرتے رہو۔ اگر ان میں سے ایک یا دونوں تمہارے سامنے بڑھاپے کو پہنچ جائیں تو اُن کو اُف تک نہ کہنا اور نہ انہیں جھڑکنا اور اُن سے بات ادب کے ساتھ کرنا','For your Lord has decreed that you worship none but Him. And honour your parents. If one or both of them reach old age in your care, never say to them ˹even˺ ‘ugh,’ nor yell at them. Rather, address them respectfully','और तुम्हारे परवरदिगार ने तो हुक्म ही दिया है कि उसके सिवा किसी दूसरे की इबादत न करना और माँ बाप से नेकी करना अगर उनमें से एक या दोनों तेरे सामने बुढ़ापे को पहुँचे (और किसी बात पर खफा हों) तो (ख़बरदार उनके जवाब में उफ तक) न कहना और न उनको झिड़कना और जो कुछ कहना सुनना हो तो बहुत अदब से कहा करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,24,'Al-Israa','وَٱخۡفِضۡ لَهُمَا جَنَاحَ ٱلذُّلِّ مِنَ ٱلرَّحۡمَةِ وَقُل رَّبِّ ٱرۡحَمۡهُمَا كَمَا رَبَّيَانِي صَغِيرࣰ ا','اور عجزو نیاز سے ان کے آگے جھکے رہو اور ان کے حق میں دعا کرو کہ اے پروردگار جیسا انہوں نے مجھے بچپن میں (شفقت سے) پرورش کیا ہے تو بھی اُن (کے حال) پر رحمت فرما','And be humble with them out of mercy, and pray, “My Lord! Be merciful to them as they raised me when I was young.”','और उनके सामने नियाज़ (रहमत) से ख़ाकसारी का पहलू झुकाए रखो और उनके हक़ में दुआ करो कि मेरे पालने वाले जिस तरह इन दोनों ने मेरे छोटेपन में मेरी मेरी परवरिश की है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,25,'Al-Israa','رَّبُّكُمۡ أَعۡلَمُ بِمَا فِي نُفُوسِكُمۡۚ إِن تَكُونُواْ صَٰلِحِينَ فَإِنَّهُۥ كَانَ لِلۡأَوَّٰبِينَ غَفُورࣰ ا','جو کچھ تمہارے دلوں میں ہے تمہارا پروردگار اس سے بخوبی واقف ہے۔ اگر تم نیک ہوگے تو وہ رجوع لانے والوں کو بخش دینے والا ہے','Your Lord knows best what is within yourselves. If you are righteous, He is certainly All-Forgiving to those who ˹constantly˺ turn to Him','इसी तरह तू भी इन पर रहम फरमा तुम्हारे दिल की बात तुम्हारा परवरदिगार ख़ूब जानता है अगर तुम (वाक़ई) नेक होगे और भूले से उनकी ख़ता की है तो वह तुमको बख्श देगा क्योंकि वह तो तौबा करने वालों का बड़ा बख़शने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,26,'Al-Israa','وَءَاتِ ذَا ٱلۡقُرۡبَىٰ حَقَّهُۥ وَٱلۡمِسۡكِينَ وَٱبۡنَ ٱلسَّبِيلِ وَلَا تُبَذِّرۡ تَبۡذِيرًا','اور رشتہ داروں اور محتاجوں اور مسافروں کو ان کا حق ادا کرو۔ اور فضول خرچی سے مال نہ اُڑاؤ','Give to close relatives their due, as well as the poor and ˹needy˺ travellers. And do not spend wastefully','और क़राबतदारों और मोहताज और परदेसी को उनका हक़ दे दो और ख़बरदार फुज़ूल ख़र्ची मत किया करो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,27,'Al-Israa','إِنَّ ٱلۡمُبَذِّرِينَ كَانُوٓاْ إِخۡوَٰنَ ٱلشَّيَٰطِينِۖ وَكَانَ ٱلشَّيۡطَٰنُ لِرَبِّهِۦ كَفُورࣰ ا','کہ فضول خرچی کرنے والے تو شیطان کے بھائی ہیں۔ اور شیطان اپنے پروردگار (کی نعمتوں) کا کفر ان کرنے والا (یعنی ناشکرا) ہے','Surely the wasteful are ˹like˺ brothers to the devils. And the Devil is ever ungrateful to his Lord','क्योंकि फुज़ूलख़र्ची करने वाले यक़ीनन शैतानों के भाई है और शैतान अपने परवरदिगार का बड़ा नाशुक्री करने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,28,'Al-Israa','وَإِمَّا تُعۡرِضَنَّ عَنۡهُمُ ٱبۡتِغَآءَ رَحۡمَةࣲ مِّن رَّبِّكَ تَرۡجُوهَا فَقُل لَّهُمۡ قَوۡلࣰ ا مَّيۡسُورࣰ ا','اور اگر تم نے اپنے پروردگار کی رحمت (یعنی فراخ دستی) کے انتظار میں جس کی تمہیں امید ہو ان (مستحقین) کی طرف توجہ نہ کرسکو اُن سے نرمی سے بات کہہ دیا کرو','But if you must turn them down ˹because you lack the means to give˺—while hoping to receive your Lord’s bounty—then ˹at least˺ give them a kind word','और तुमको अपने परवरदिगार के फज़ल व करम के इन्तज़ार में जिसकी तुम को उम्मीद हो (मजबूरन) उन (ग़रीबों) से मुँह मोड़ना पड़े तो नरमी से उनको समझा दो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,29,'Al-Israa','وَلَا تَجۡعَلۡ يَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبۡسُطۡهَا كُلَّ ٱلۡبَسۡطِ فَتَقۡعُدَ مَلُومࣰ ا مَّحۡسُورًا','اور اپنے ہاتھ کو نہ تو گردن سے بندھا ہوا (یعنی بہت تنگ) کرلو (کہ کسی کچھ دو ہی نہیں) اور نہ بالکل کھول ہی دو (کہ سبھی دے ڈالو اور انجام یہ ہو) کہ ملامت زدہ اور درماندہ ہو کر بیٹھ جاؤ','Do not be so tight-fisted, for you will be blameworthy; nor so open-handed, for you will end up in poverty','और अपने हाथ को न तो गर्दन से बँधा हुआ (बहुत तंग) कर लो (कि किसी को कुछ दो ही नहीं) और न बिल्कुल खोल दो कि सब कुछ दे डालो और आख़िर तुम को मलामत ज़दा हसरत से बैठना पड़े');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,30,'Al-Israa','إِنَّ رَبَّكَ يَبۡسُطُ ٱلرِّزۡقَ لِمَن يَشَآءُ وَيَقۡدِرُۚ إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرَۢا بَصِيرࣰ ا','بےشک تمہارا پروردگار جس کی روزی چاہتا ہے فراخ کردیتا ہے اور (جس کی روزی چاہتا ہے) تنگ کردیتا ہے وہ اپنے بندوں سے خبردار ہے اور (ان کو) دیکھ رہا ہے','Surely your Lord gives abundant or limited provisions to whoever He wills. He is certainly All-Aware, All-Seeing of His servants','इसमें शक़ नहीं कि तुम्हारा परवरदिगार जिसके लिए चाहता है रोज़ी को फराख़ (बढ़ा) देता है और जिसकी रोज़ी चाहता है तंग रखता है इसमें शक़ नहीं कि वह अपने बन्दों से बहुत बाख़बर और देखभाल रखने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,31,'Al-Israa','وَلَا تَقۡتُلُوٓاْ أَوۡلَٰدَكُمۡ خَشۡيَةَ إِمۡلَٰقࣲۖ نَّحۡنُ نَرۡزُقُهُمۡ وَإِيَّاكُمۡۚ إِنَّ قَتۡلَهُمۡ كَانَ خِطۡـࣰٔ ا كَبِيرࣰ ا','اور اپنی اولاد کو مفلسی کے خوف سے قتل نہ کرنا۔ (کیونکہ) ان کو اور تم کو ہم ہی رزق دیتے ہیں۔ کچھ شک نہیں کہ ان کا مار ڈالنا بڑا سخت گناہ ہے','Do not kill your children for fear of poverty. We provide for them and for you. Surely killing them is a heinous sin','और (लोगों) मुफलिसी (ग़रीबी) के ख़ौफ से अपनी औलाद को क़त्ल न करो (क्योंकि) उनको और तुम को (सबको) तो हम ही रोज़ी देते हैं बेशक औलाद का क़त्ल करना बहुत सख्त गुनाह है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,32,'Al-Israa','وَلَا تَقۡرَبُواْ ٱلزِّنَىٰٓۖ إِنَّهُۥ كَانَ فَٰحِشَةࣰ وَسَآءَ سَبِيلࣰ ا','اور زنا کے بھی پاس نہ جانا کہ وہ بےحیائی اور بری راہ ہے','Do not go near adultery. It is truly a shameful deed and an evil way','और (देखो) ज़िना के पास भी न फटकना क्योंकि बेशक वह बड़ी बेहयाई का काम है और बहुत बुरा चलन है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,33,'Al-Israa','وَلَا تَقۡتُلُواْ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۗ وَمَن قُتِلَ مَظۡلُومࣰ ا فَقَدۡ جَعَلۡنَا لِوَلِيِّهِۦ سُلۡطَٰنࣰ ا فَلَا يُسۡرِف فِّي ٱلۡقَتۡلِۖ إِنَّهُۥ كَانَ مَنصُورࣰ ا','اور جس کا جاندار کا مارنا خدا نے حرام کیا ہے اسے قتل نہ کرنا مگر جائز طور پر (یعنی بفتویٰ شریعت) ۔ اور جو شخص ظلم سے قتل کیا جائے ہم نے اس کے وارث کو اختیار دیا ہے (کہ ظالم قاتل سے بدلہ لے) تو اس کو چاہیئے کہ قتل (کے قصاص) میں زیادتی نہ کرے کہ وہ منصورو فتحیاب ہے','Do not take a ˹human˺ life—made sacred by Allah—except with ˹legal˺ right. If anyone is killed unjustly, We have given their heirs the authority, but do not let them exceed limits in retaliation, for they are already supported ˹by law˺','और जिस जान का मारना ख़ुदा ने हराम कर दिया है उसके क़त्ल न करना मगर जायज़ तौर पर और जो शख़्श नाहक़ मारा जाए तो हमने उसके वारिस को (क़ातिल पर क़सास का क़ाबू दिया है तो उसे चाहिए कि क़त्ल (ख़ून का बदला लेने) में ज्यादती न करे बेशक वह मदद दिया जाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,34,'Al-Israa','وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ حَتَّىٰ يَبۡلُغَ أَشُدَّهُۥۚ وَأَوۡفُواْ بِٱلۡعَهۡدِۖ إِنَّ ٱلۡعَهۡدَ كَانَ مَسۡـُٔولࣰ ا','اور یتیم کے مال کے پاس بھی نہ پھٹکنا مگر ایسے طریق سے کہ بہت بہتر ہو یہاں تک کہ ہو جوانی کو پہنچ جائے۔ اور عہد کو پورا کرو کہ عہد کے بارے میں ضرور پرسش ہوگی','Do not come near the wealth of the orphan—unless intending to enhance it—until they attain maturity. Honour ˹your˺ pledges, for you will surely be accountable for them','(कि क़त्ल ही करे और माफ न करे) और यतीम जब तक जवानी को पहुँचे उसके माल के क़रीब भी न पहुँच जाना मगर हाँ इस तरह पर कि (यतीम के हक़ में) बेहतर हो और एहद को पूरा करो क्योंकि (क़यामत में) एहद की ज़रुर पूछ गछ होगी');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,35,'Al-Israa','وَأَوۡفُواْ ٱلۡكَيۡلَ إِذَا كِلۡتُمۡ وَزِنُواْ بِٱلۡقِسۡطَاسِ ٱلۡمُسۡتَقِيمِۚ ذَٰلِكَ خَيۡرࣱ وَأَحۡسَنُ تَأۡوِيلࣰ ا','اور جب (کوئی چیز) ناپ کر دینے لگو تو پیمانہ پورا بھرا کرو اور (جب تول کر دو تو) ترازو سیدھی رکھ کر تولا کرو۔ یہ بہت اچھی بات اور انجام کے لحاظ سے بھی بہت بہتر ہے','Give in full when you measure, and weigh with an even balance. That is fairest and best in the end','और जब नाप तौल कर देना हो तो पैमाने को पूरा भर दिया करो और (जब तौल कर देना हो तो) बिल्कुल ठीक तराजू से तौला करो (मामले में) यही (तरीक़ा) बेहतर है और अन्जाम (भी उसका) अच्छा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,36,'Al-Israa','وَلَا تَقۡفُ مَا لَيۡسَ لَكَ بِهِۦ عِلۡمٌۚ إِنَّ ٱلسَّمۡعَ وَٱلۡبَصَرَ وَٱلۡفُؤَادَ كُلُّ أُوْلَٰٓئِكَ كَانَ عَنۡهُ مَسۡـُٔولࣰ ا','اور (اے بندے) جس چیز کا تجھے علم نہیں اس کے پیچھے نہ پڑ۔ کہ کان اور آنکھ اور دل ان سب (جوارح) سے ضرور باز پرس ہوگی','Do not follow what you have no ˹sure˺ knowledge of. Indeed, all will be called to account for ˹their˺ hearing, sight, and intellect','और जिस चीज़ का कि तुम्हें यक़ीन न हो (ख्वाह मा ख्वाह) उसके पीछे न पड़ा करो (क्योंकि) कान और ऑंख और दिल इन सबकी (क़यामत के दिना यक़ीनन बाज़पुर्स होती है)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,37,'Al-Israa','وَلَا تَمۡشِ فِي ٱلۡأَرۡضِ مَرَحًاۖ إِنَّكَ لَن تَخۡرِقَ ٱلۡأَرۡضَ وَلَن تَبۡلُغَ ٱلۡجِبَالَ طُولࣰ ا','اور زمین پر اکڑ کر (اور تن کر) مت چل کہ تو زمین کو پھاڑ تو نہیں ڈالے گا اور نہ لمبا ہو کر پہاڑوں (کی چوٹی) تک پہنچ جائے گا','And do not walk on the earth arrogantly. Surely you can neither crack the earth nor stretch to the height of the mountains','और (देखो) ज़मीन पर अकड़ कर न चला करो क्योंकि तू (अपने इस धमाके की चाल से) न तो ज़मीन को हरगिज़ फाड़ डालेगा और न (तनकर चलने से) हरगिज़ लम्बाई में पहाड़ों के बराबर पहुँच सकेगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,38,'Al-Israa','كُلُّ ذَٰلِكَ كَانَ سَيِّئُهُۥ عِندَ رَبِّكَ مَكۡرُوهࣰ ا','ان سب (عادتوں) کی برائی تیرے پروردگار کے نزدیک بہت ناپسند ہے','The violation of any of these ˹commandments˺ is detestable to your Lord','(ऐ रसूल) इन सब बातों में से जो बुरी बात है वह तुम्हारे परवरदिगार के नज़दीक नापसन्द है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,39,'Al-Israa','ذَٰلِكَ مِمَّآ أَوۡحَىٰٓ إِلَيۡكَ رَبُّكَ مِنَ ٱلۡحِكۡمَةِۗ وَلَا تَجۡعَلۡ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ فَتُلۡقَىٰ فِي جَهَنَّمَ مَلُومࣰ ا مَّدۡحُورًا','اے پیغمبر یہ ان (ہدایتوں) میں سے ہیں جو خدا نے دانائی کی باتیں تمہاری طرف وحی کی ہیں۔ اور خدا کے ساتھ کوئی معبود نہ بنانا کہ (ایسا کرنے سے) ملامت زدہ اور (درگاہ خدا سے) راندہ بنا کر جہنم میں ڈال دیئے جاؤ گے','This is part of the wisdom which your Lord has revealed to you ˹O Prophet˺. And do not set up any other god with Allah ˹O humanity˺, or you will be cast into Hell, blameworthy, rejected','ये बात तो हिकमत की उन बातों में से जो तुम्हारे परवरदिगार ने तुम्हारे पास ''वही'' भेजी और ख़ुदा के साथ कोई दूसरा माबूद न बनाना और न तू मलामत ज़दा राइन्द (धुत्कारा) होकर जहन्नुम में झोंक दिया जाएगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,40,'Al-Israa','أَفَأَصۡفَىٰكُمۡ رَبُّكُم بِٱلۡبَنِينَ وَٱتَّخَذَ مِنَ ٱلۡمَلَٰٓئِكَةِ إِنَٰثًاۚ إِنَّكُمۡ لَتَقُولُونَ قَوۡلًا عَظِيمࣰ ا','(مشرکو!) کیا تمہارے پروردگار نے تم کو لڑکے دیئے اور خود فرشتوں کو بیٹیاں بنایا۔ کچھ شک نہیں کہ (یہ) تم بڑی (نامعقول بات) کہتے ہو','Has your Lord favoured you ˹pagans˺ with sons and taken angels as ˹His˺ daughters? You are truly making an outrageous claim','(ऐ मुशरेकीन मक्का) क्या तुम्हारे परवरदिगार ने तुम्हें चुन चुन कर बेटे दिए हैं और खुद बेटियाँ ली हैं (यानि) फरिश्ते इसमें शक़ नहीं कि बड़ी (सख्त) बात कहते हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,41,'Al-Israa','وَلَقَدۡ صَرَّفۡنَا فِي هَٰذَا ٱلۡقُرۡءَانِ لِيَذَّكَّرُواْ وَمَا يَزِيدُهُمۡ إِلَّا نُفُورࣰ ا','اور ہم نے اس قرآن میں طرح طرح کی باتیں بیان کی ہیں تاکہ لوگ نصیحت پکڑیں گے۔ مگر وہ اس سے اور بدک جاتے ہیں','We have surely varied ˹the signs˺ in this Quran so perhaps they may be mindful, but it only drives them farther away','और हमने तो इसी क़ुरान में तरह तरह से बयान कर दिया ताकि लोग किसी तरह समझें मगर उससे तो उनकी नफरत ही बढ़ती गई');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,42,'Al-Israa','قُل لَّوۡ كَانَ مَعَهُۥٓ ءَالِهَةࣱ كَمَا يَقُولُونَ إِذࣰ ا لَّٱبۡتَغَوۡاْ إِلَىٰ ذِي ٱلۡعَرۡشِ سَبِيلࣰ ا','کہہ دو کہ اگر خدا کے ساتھ اور معبود ہوتے جیسا کہ یہ کہتے ہیں تو وہ ضرور (خدائے) مالک عرش کی طرف (لڑنے بھڑنے کے لئے) رستہ نکالتے','Say, ˹O Prophet,˺ “Had there been other gods besides Him—as they claim—then they would have certainly sought a way to ˹challenge˺ the Lord of the Throne.”','(ऐ रसूल उनसे) तुम कह दो कि अगर ख़ुदा के साथ जैसा ये लोग कहते हैं और माबूद भी होते तो अब तक उन माबूदों ने अर्श तक (पहुँचाने की कोई न कोई राह निकाल ली होती)');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,43,'Al-Israa','سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يَقُولُونَ عُلُوࣰّ ا كَبِيرࣰ ا','وہ پاک ہے اور جو کچھ یہ بکواس کرتے ہیں اس سے (اس کا رتبہ) بہت عالی ہے','Glorified and Highly Exalted is He above what they claim','जो बेहूदा बातें ये लोग (ख़ुदा की निस्बत) कहा करते हैं वह उनसे बहुत बढ़के पाक व पाकीज़ा और बरतर है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,44,'Al-Israa','تُسَبِّحُ لَهُ ٱلسَّمَٰوَٰتُ ٱلسَّبۡعُ وَٱلۡأَرۡضُ وَمَن فِيهِنَّۚ وَإِن مِّن شَيۡءٍ إِلَّا يُسَبِّحُ بِحَمۡدِهِۦ وَلَٰكِن لَّا تَفۡقَهُونَ تَسۡبِيحَهُمۡۚ إِنَّهُۥ كَانَ حَلِيمًا غَفُورࣰ ا','ساتوں آسمان اور زمین اور جو لوگ ان میں ہیں سب اسی کی تسبیح کرتے ہیں۔ اور (مخلوقات میں سے) کوئی چیز نہیں مگر اس کی تعریف کے ساتھ تسبیح کرتی ہے۔ لیکن تم ان کی تسبیح کو نہیں سمجھتے۔ بےشک وہ بردبار (اور) غفار ہے','The seven heavens, the earth, and all those in them glorify Him. There is not a single thing that does not glorify His praises—but you ˹simply˺ cannot comprehend their glorification. He is indeed Most Forbearing, All-Forgiving','सातों आसमान और ज़मीन और जो लोग इनमें (सब) उसकी तस्बीह करते हैं और (सारे जहाँन) में कोई चीज़ ऐसी नहीं जो उसकी (हम्द व सना) की तस्बीह न करती हो मगर तुम लोग उनकी तस्बीह नहीं समझते इसमें शक़ नहीं कि वह बड़ा बुर्दबार बख्शने वाला है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,45,'Al-Israa','وَإِذَا قَرَأۡتَ ٱلۡقُرۡءَانَ جَعَلۡنَا بَيۡنَكَ وَبَيۡنَ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ حِجَابࣰ ا مَّسۡتُورࣰ ا','اور جب قرآن پڑھا کرتے ہو تو ہم تم میں اور ان لوگوں میں جو آخرت پر ایمان نہیں رکھتے حجاب پر حجاب کر دیتے ہیں','When you ˹O Prophet˺ recite the Quran, We put a hidden barrier between you and those who do not believe in the Hereafter','और जब तुम क़ुरान पढ़ते हो तो हम तुम्हारे और उन लोगों के दरमियान जो आख़िरत का यक़ीन नहीं रखते एक गहरा पर्दा डाल देते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,46,'Al-Israa','وَجَعَلۡنَا عَلَىٰ قُلُوبِهِمۡ أَكِنَّةً أَن يَفۡقَهُوهُ وَفِيٓ ءَاذَانِهِمۡ وَقۡرࣰ اۚ وَإِذَا ذَكَرۡتَ رَبَّكَ فِي ٱلۡقُرۡءَانِ وَحۡدَهُۥ وَلَّوۡاْ عَلَىٰٓ أَدۡبَٰرِهِمۡ نُفُورࣰ ا','اور ان کے دلوں پر پردہ ڈال دیتے ہیں کہ اسے سمجھ نہ سکیں اور ان کے کانوں میں ثقل پیدا کر دیتے ہیں۔ اور جب تم قرآن میں اپنے پروردگار یکتا کا ذکر کرتے ہو تو وہ بدک جاتے اور پیٹھ پھیر کر چل دیتے ہیں','We have cast veils over their hearts—leaving them unable to comprehend it—and deafness in their ears. And when you mention your Lord alone in the Quran, they turn their backs in aversion','और (गोया) हम उनके कानों में गरानी पैदा कर देते हैं कि न सुन सकें जब तुम क़ुरान में अपने परवरदिगार का तन्हा ज़िक्र करते हो तो कुफ्फार उलटे पावँ नफरत करके (तुम्हारे पास से) भाग खड़े होते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,47,'Al-Israa','نَّحۡنُ أَعۡلَمُ بِمَا يَسۡتَمِعُونَ بِهِۦٓ إِذۡ يَسۡتَمِعُونَ إِلَيۡكَ وَإِذۡ هُمۡ نَجۡوَىٰٓ إِذۡ يَقُولُ ٱلظَّٰلِمُونَ إِن تَتَّبِعُونَ إِلَّا رَجُلࣰ ا مَّسۡحُورًا','یہ لوگ جب تمہاری طرف کان لگاتے ہیں تو جس نیت سے یہ سنتے ہیں ہم اسے خوب جانتے ہیں اور جب یہ سرگوشیاں کرتے ہیں (یعنی) جب ظالم کہتے ہیں کہ تم ایک ایسے شخص کی پیروی کرتے ہو جس پر جادو کیا گیا ہے','We know best how they listen to your recitation and what they say privately—when the wrongdoers say, “You would only be following a bewitched man.”','जब ये लोग तुम्हारी तरफ कान लगाते हैं तो जो कुछ ये ग़ौर से सुनते हैं हम तो खूब जानते हैं और जब ये लोग बाहम कान में बात करते हैं तो उस वक्त ये ज़ालिम (ईमानदारों से) कहते हैं कि तुम तो बस एक (दीवाने) आदमी के पीछे पड़े हो जिस पर किसी ने जादू कर दिया है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,48,'Al-Israa','ٱنظُرۡ كَيۡفَ ضَرَبُواْ لَكَ ٱلۡأَمۡثَالَ فَضَلُّواْ فَلَا يَسۡتَطِيعُونَ سَبِيلࣰ ا','دیکھو انہوں نے کس کس طرح کی تمہارے بارے میں باتیں بنائیں ہیں۔ سو یہ گمراہ ہو رہے ہیں اور رستہ نہیں پاسکتے','See how they call you names ˹O Prophet˺! So they have gone so ˹far˺ astray that they cannot find the ˹Right˺ Way','(ऐ रसूल) ज़रा देखो तो ये कम्बख्त तुम्हारी निस्बत कैसी कैसी फब्तियाँ कहते हैं तो (इसी वजह से) ऐसे गुमराह हुए कि अब (हक़ की) राह किसी तरह पा ही नहीं सकते');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,49,'Al-Israa','وَقَالُوٓاْ أَءِذَا كُنَّا عِظَٰمࣰ ا وَرُفَٰتًا أَءِنَّا لَمَبۡعُوثُونَ خَلۡقࣰ ا جَدِيدࣰ ا','اور کہتے ہیں کہ جب ہم (مر کر بوسیدہ) ہڈیوں اور چُور چُور ہوجائیں گے تو کیا ازسرنو پیدا ہو کر اُٹھیں گے','And they say ˹mockingly˺, “When we are reduced to bones and ashes, will we really be raised as a new creation?”','और ये लोग कहते हैं कि जब हम (मरने के बाद सड़ गल कर) हड्डियाँ रह जाएँगें और रेज़ा रेज़ा हो जाएँगें तो क्या नये सिरे से पैदा करके उठा खड़े किए जाएँगें');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,50,'Al-Israa','۞قُلۡ كُونُواْ حِجَارَةً أَوۡ حَدِيدًا','کہہ دو کہ (خواہ تم) پتھر ہوجاؤ یا لوہا','Say, ˹O Prophet,˺ “˹Yes, even if˺ you become stones, or iron','(ऐ रसूल) तुम कह दो कि तुम (मरने के बाद) चाहे पत्थर बन जाओ या लोहा या कोई और चीज़ जो तुम्हारे ख्याल में बड़ी (सख्त) हो');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,51,'Al-Israa','أَوۡ خَلۡقࣰ ا مِّمَّا يَكۡبُرُ فِي صُدُورِكُمۡۚ فَسَيَقُولُونَ مَن يُعِيدُنَاۖ قُلِ ٱلَّذِي فَطَرَكُمۡ أَوَّلَ مَرَّةࣲۚ فَسَيُنۡغِضُونَ إِلَيۡكَ رُءُوسَهُمۡ وَيَقُولُونَ مَتَىٰ هُوَۖ قُلۡ عَسَىٰٓ أَن يَكُونَ قَرِيبࣰ ا','یا کوئی اور چیز جو تمہارے نزدیک (پتھر اور لوہے سے بھی) بڑی (سخت) ہو (جھٹ کہیں گے) کہ (بھلا) ہمیں دوبارہ کون جِلائے گا؟ کہہ دو کہ وہی جس نے تم کو پہلی بار پیدا کیا۔ تو (تعجب سے) تمہارے آگے سرہلائیں گے اور پوچھیں گے کہ ایسا کب ہوگا؟ کہہ دو کہ امید ہے جلد ہوگا','or whatever you think is harder to bring to life!” Then they will ask ˹you˺, “Who will bring us back ˹to life˺?” Say, “The One Who created you the first time.” They will then shake their heads at you and ask, “When will that be?” Say, “Perhaps it is soon!”','और उसका ज़िन्दा होना दुश्वार हो वह भी ज़रुर ज़िन्दा हो गई तो ये लोग अनक़रीब ही तुम से पूछेगें भला हमें दोबारा कौन ज़िन्दा करेगा तुम कह दो कि वही (ख़ुदा) जिसने तुमको पहली मरतबा पैदा किया (जब तुम कुछ न थे) इस पर ये लोग तुम्हारे सामने अपने सर मटकाएँगें और कहेगें (अच्छा अगर होगा) तो आख़िर कब तुम कह दो कि बहुत जल्द अनक़रीब ही होगा');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,52,'Al-Israa','يَوۡمَ يَدۡعُوكُمۡ فَتَسۡتَجِيبُونَ بِحَمۡدِهِۦ وَتَظُنُّونَ إِن لَّبِثۡتُمۡ إِلَّا قَلِيلࣰ ا','جس دن وہ تمہیں پکارے گا تو تم اس کی تعریف کے ساتھ جواب دو گے اور خیال کرو گے کہ تم (دنیا میں) بہت کم (مدت) رہے','On the Day He will call you, you will ˹instantly˺ respond by praising Him, thinking you had remained ˹in the world˺ only for a little while','जिस दिन ख़ुदा तुम्हें (इसराफील के ज़रिए से) बुंलाएगा तो उसकी हम्दो सना करते हुए उसकी तामील करोगे (और क़ब्रों से निकलोगे) और तुम ख्याल करोगे कि (मरने के बाद क़ब्रों में) बहुत ही कम ठहरे');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,53,'Al-Israa','وَقُل لِّعِبَادِي يَقُولُواْ ٱلَّتِي هِيَ أَحۡسَنُۚ إِنَّ ٱلشَّيۡطَٰنَ يَنزَغُ بَيۡنَهُمۡۚ إِنَّ ٱلشَّيۡطَٰنَ كَانَ لِلۡإِنسَٰنِ عَدُوࣰّ ا مُّبِينࣰ ا','اور میرے بندوں سے کہہ دو کہ (لوگوں سے) ایسی باتیں کہا کریں جو بہت پسندیدہ ہوں۔ کیونکہ شیطان (بری باتوں سے) ان میں فساد ڈلوا دیتا ہے۔ کچھ شک نہیں کہ شیطان انسان کا کھلا دشمن ہے','Tell My ˹believing˺ servants to say only what is best. Satan certainly seeks to sow discord among them. Satan is indeed a sworn enemy to humankind','और (ऐ रसूल) मेरे (सच्चे) बन्दों (मोमिनों से कह दो कि वह (काफिरों से) बात करें तो अच्छे तरीक़े से (सख्त कलामी न करें) क्योंकि शैतान तो (ऐसी ही) बातों से फसाद डलवाता है इसमें तो शक़ ही नहीं कि शैतान आदमी का खुला हुआ दुश्मन है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,54,'Al-Israa','رَّبُّكُمۡ أَعۡلَمُ بِكُمۡۖ إِن يَشَأۡ يَرۡحَمۡكُمۡ أَوۡ إِن يَشَأۡ يُعَذِّبۡكُمۡۚ وَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ وَكِيلࣰ ا','تمہارا پروردگار تم سے خوب واقف ہے۔ اگر چاہے تو تم پر رحم کرے یا اگر چاہے تو تمہیں عذاب دے۔ اور ہم نے تم کو ان پر داروغہ (بنا کر) نہیں بھیجا','Your Lord knows you best. He may have mercy on you if He wills, or punish you if He wills. We have not sent you ˹O Prophet˺ as a keeper over them','तुम्हारा परवरदिगार तुम्हारे हाल से खूब वाक़िफ है अगर चाहेगा तुम पर रहम करेगा और अगर चाहेगा तुम पर अज़ाब करेगा और (ऐ रसूल) हमने तुमको कुछ उन लोगों का ज़िम्मेदार बनाकर नहीं भेजा है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,55,'Al-Israa','وَرَبُّكَ أَعۡلَمُ بِمَن فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۗ وَلَقَدۡ فَضَّلۡنَا بَعۡضَ ٱلنَّبِيِّـۧنَ عَلَىٰ بَعۡضࣲۖ وَءَاتَيۡنَا دَاوُۥدَ زَبُورࣰ ا','اور جو لوگ آسمانوں اور زمین میں ہیں تمہارا پروردگار ان سے خوب واقف ہے۔ اور ہم نے بعض پیغمبروں کو بعض پر فضیلت بخشی اور داؤد کو زبور عنایت کی','Your Lord knows best all those in the heavens and the earth. And We have surely favoured some prophets above others, and to David We gave the Psalms','और जो लोग आसमानों में है और ज़मीन पर हैं (सब को) तुम्हारा परवरदिगार खूब जानता है और हम ने यक़ीनन बाज़ पैग़म्बरों को बाज़ पर फज़ीलत दी और हम ही ने दाऊद को जूबूर अता की');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,56,'Al-Israa','قُلِ ٱدۡعُواْ ٱلَّذِينَ زَعَمۡتُم مِّن دُونِهِۦ فَلَا يَمۡلِكُونَ كَشۡفَ ٱلضُّرِّ عَنكُمۡ وَلَا تَحۡوِيلًا','کہو کہ (مشرکو) جن لوگوں کی نسبت تمہیں (معبود ہونے کا) گمان ہے ان کو بلا کر دیکھو۔ وہ تم سے تکلیف کے دور کرنے یا اس کے بدل دینے کا کچھ بھی اختیار نہیں رکھتے','Say, ˹O Prophet,˺ “Invoke those you claim ˹to be divine˺ besides Him—they do not have the power to undo harm from you or transfer it ˹to someone else˺.”','(ऐ रसूल) तुम उनसे कह दों कि ख़ुदा के सिवा और जिन लोगों को माबूद समझते हो उनको (वक्त पडे) पुकार के तो देखो कि वह न तो तुम से तुम्हारी तकलीफ ही दफा कर सकते हैं और न उसको बदल सकते हैं');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,57,'Al-Israa','أُوْلَٰٓئِكَ ٱلَّذِينَ يَدۡعُونَ يَبۡتَغُونَ إِلَىٰ رَبِّهِمُ ٱلۡوَسِيلَةَ أَيُّهُمۡ أَقۡرَبُ وَيَرۡجُونَ رَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ إِنَّ عَذَابَ رَبِّكَ كَانَ مَحۡذُورࣰ ا','یہ لوگ جن کو (خدا کے سوا) پکارتے ہیں وہ خود اپنے پروردگار کے ہاں ذریعہ (تقرب) تلاش کرتے رہتے ہیں کہ کون ان میں (خدا کا) زیادہ مقرب ہوتا ہے اور اس کی رحمت کے امیدوار رہتے ہیں اور اس کے عذاب سے خوف رکھتے ہیں۔ بےشک تمہارے پروردگار کا عذاب ڈرنے کی چیز ہے','˹Even˺ the closest ˹to Allah˺ of those invoked would be seeking a way to their Lord, hoping for His mercy, and fearing His punishment. Indeed, your Lord’s torment is fearsome','ये लोग जिनको मुशरेकीन (अपना ख़ुदा समझकर) इबादत करते हैं वह खुद अपने परवरदिगार की क़ुरबत के ज़रिए ढूँढते फिरते हैं कि (देखो) इनमें से कौन ज्यादा कुरबत रखता है और उसकी रहमत की उम्मीद रखते और उसके अज़ाब से डरते हैं इसमें शक़ नहीं कि तेरे परवरदिगार का अज़ाब डरने की चीज़ है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,58,'Al-Israa','وَإِن مِّن قَرۡيَةٍ إِلَّا نَحۡنُ مُهۡلِكُوهَا قَبۡلَ يَوۡمِ ٱلۡقِيَٰمَةِ أَوۡ مُعَذِّبُوهَا عَذَابࣰ ا شَدِيدࣰ اۚ كَانَ ذَٰلِكَ فِي ٱلۡكِتَٰبِ مَسۡطُورࣰ ا','اور (کفر کرنے والوں کی) کوئی بستی نہیں مگر قیامت کے دن سے پہلے ہم اسے ہلاک کردیں گے یا سخت عذاب سے معذب کریں گے۔ یہ کتاب (یعنی تقدیر) میں لکھا جاچکا ہے','There is not a ˹wicked˺ society that We will not destroy or punish with a severe torment before the Day of Judgment. That is written in the Record','और कोई बस्ती नहीं है मगर रोज़ क़यामत से पहले हम उसे तबाह व बरबाद कर छोड़ेगें या (नाफरमानी) की सज़ा में उस पर सख्त से सख्त अज़ाब करेगें (और) ये बात किताब (लौहे महफूज़) में लिखी जा चुकी है');
INSERT INTO verses_fts(surah,verse,sname,ar,ur,en,hi) VALUES (17,59,'Al-Israa','وَمَا مَنَعَنَآ أَن نُّرۡسِلَ بِٱلۡأٓيَٰتِ إِلَّآ أَن كَذَّبَ بِهَا ٱلۡأَوَّلُونَۚ وَءَاتَيۡنَا ثَمُودَ ٱلنَّاقَةَ مُبۡصِرَةࣰ فَظَلَمُواْ بِهَاۚ وَمَا نُرۡسِلُ بِٱلۡأٓيَٰتِ إِلَّا تَخۡوِيفࣰ ا','اور ہم نے نشانیاں بھیجنی اس لئے موقوف کردیں کہ اگلے لوگوں نے اس کی تکذیب کی تھی۔ اور ہم نے ثمود کو اونٹنی (نبوت صالح کی کھلی) نشانی دی۔ تو انہوں نے اس پر ظلم کیا اور ہم جو نشانیاں بھیجا کرتے ہیں تو ڈرانے کو','Nothing keeps Us from sending the ˹demanded˺ signs except that they had ˹already˺ been denied by earlier peoples. And We gave Thamûd the she-camel as a clear sign, but they wrongfully rejected it. We only send the signs as a warning','और हमें मौजिज़ात भेजने से किसी चीज़ ने नहीं रोका मगर इसके सिवा कि अगलों ने उन्हें झुठला दिया और हमने क़ौमे समूद को (मौजिज़े से) ऊँटनी अता की जो (हमारी कुदरत की) दिखाने वाली थी तो उन लोगों ने उस पर ज़ुल्म किया यहाँ तक कि मार डाला और हम तो मौजिज़े सिर्फ डराने की ग़रज़ से भेजा करते हैं');
